:root {
    --site-ink: #101914;
    --site-ink-2: #16221b;
    --site-ink-3: #1d2c23;
    --site-cream: #f3eee2;
    --site-cream-2: #e9e2d3;
    --site-gold: #c7a15a;
    --site-gold-2: #dfc087;
    --site-muted: #a8b0a9;
    --site-line: rgba(255, 255, 255, .12);
    --site-line-dark: rgba(16, 25, 20, .12);
    --font-display: 'Fraunces', Georgia, serif;
    --font-sans: 'DM Sans', ui-sans-serif, system-ui, sans-serif;
    --radius: 22px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; }
.site-body {
    background: var(--site-ink);
    color: var(--site-cream);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
}
.site-body a { color: inherit; text-decoration: none; }
.site-body img { display: block; max-width: 100%; }
.site-body button { font-family: inherit; }
.site-wrap { width: min(1240px, calc(100% - 48px)); margin-inline: auto; }
.skip-link { position: fixed; z-index: 100; left: 16px; top: -80px; background: var(--site-gold); color: #101914; padding: 12px 18px; border-radius: 8px; font-weight: 700; }
.skip-link:focus { top: 16px; }

/* ---------- Navigation ---------- */
.site-nav {
    position: sticky; top: 0; z-index: 50;
    border-bottom: 1px solid transparent;
    transition: background .35s, border-color .35s, backdrop-filter .35s;
}
.site-nav.is-scrolled {
    background: rgba(16, 25, 20, .88);
    backdrop-filter: blur(18px);
    border-bottom-color: var(--site-line);
}
.nav-inner { display: flex; align-items: center; justify-content: space-between; gap: 24px; height: 82px; }
.brand { display: inline-flex; align-items: center; gap: 12px; }
.brand-mark {
    width: 44px; height: 44px; border: 1px solid rgba(199, 161, 90, .55); border-radius: 50%;
    display: grid; place-items: center; color: var(--site-gold);
    font-family: var(--font-display); font-size: 18px; letter-spacing: -1px; flex: none;
}
.brand-text { display: grid; gap: 2px; }
.brand-text strong {
    font-family: var(--font-display); font-weight: 500; font-size: 14px;
    letter-spacing: .17em; text-transform: uppercase; line-height: 1;
}
.brand-text em { font-style: normal; font-size: 9px; letter-spacing: .30em; text-transform: uppercase; color: var(--site-muted); }
.nav-links { display: flex; align-items: center; gap: 30px; }
.nav-links a { font-size: 13px; color: #c9d0c9; position: relative; padding: 8px 0; }
.nav-links a:after {
    content: ''; position: absolute; left: 0; bottom: 0; height: 1px; width: 0;
    background: var(--site-gold); transition: width .3s;
}
.nav-links a:hover, .nav-links a.is-active { color: var(--site-cream); }
.nav-links a:hover:after, .nav-links a.is-active:after { width: 100%; }
.nav-actions { display: flex; align-items: center; gap: 18px; }
.nav-login { font-size: 13px; color: #c9d0c9; }
.nav-login:hover { color: var(--site-gold); }
.menu-toggle {
    display: none; width: 42px; height: 42px; background: transparent; border: 1px solid var(--site-line);
    border-radius: 50%; padding: 12px; cursor: pointer;
}
.menu-toggle span { display: block; height: 1px; background: var(--site-cream); margin: 5px 0; }
.mobile-menu {
    display: none; padding: 8px 24px 24px; gap: 0; background: rgba(16, 25, 20, .97);
    border-bottom: 1px solid var(--site-line);
}
.mobile-menu a { padding: 15px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 15px; }
.mobile-menu a.is-gold { color: var(--site-gold); }
.mobile-menu.is-open { display: grid; }

/* ---------- Buttons ---------- */
.btn {
    display: inline-flex; align-items: center; justify-content: center; gap: 9px;
    min-height: 48px; padding: 13px 23px; border-radius: 999px;
    font-size: 13px; font-weight: 600; letter-spacing: .01em;
    border: 1px solid transparent; cursor: pointer; transition: .28s ease;
    white-space: nowrap;
}
.btn svg { width: 16px; height: 16px; }
.btn-gold { background: var(--site-gold); color: #14130e; }
.btn-gold:hover { background: var(--site-gold-2); transform: translateY(-2px); box-shadow: 0 14px 34px rgba(199,161,90,.18); }
.btn-line { border-color: rgba(255,255,255,.20); color: var(--site-cream); }
.btn-line:hover { border-color: rgba(199,161,90,.7); color: var(--site-gold); transform: translateY(-2px); }
.btn-dark { background: var(--site-ink); color: var(--site-cream); }
.btn-dark:hover { background: #203128; }
.btn-cream { background: var(--site-cream); color: #142019; }
.btn-cream:hover { background: #fff; }
.btn-small { min-height: 40px; padding: 10px 17px; font-size: 12px; }
.btn-block { width: 100%; }

/* ---------- Hero ---------- */
.hero-wedding {
    position: relative; display: grid; grid-template-columns: 1.08fr .92fr;
    gap: 64px; align-items: center; padding: 82px 0 72px;
}
.hero-wedding:before {
    content: ''; position: absolute; width: 620px; height: 620px; left: -240px; top: -220px;
    background: radial-gradient(circle, rgba(199,161,90,.12), transparent 66%); pointer-events: none;
}
.hero-eyebrow, .eyebrow {
    display: inline-flex; align-items: center; gap: 11px; color: var(--site-gold);
    font-size: 10px; font-weight: 600; letter-spacing: .28em; text-transform: uppercase;
}
.hero-eyebrow:before, .eyebrow:before { content: ''; width: 28px; height: 1px; background: var(--site-gold); }
.hero-title {
    margin: 26px 0 0; font-family: var(--font-display); font-weight: 300;
    font-size: clamp(48px, 6.3vw, 88px); line-height: .95; letter-spacing: -.035em;
}
.hero-title em { color: var(--site-gold); font-style: italic; font-weight: 300; }
.hero-lead { margin: 30px 0 0; max-width: 560px; color: #b8c0b9; font-size: 16px; line-height: 1.8; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 36px; }
.hero-trust { display: flex; align-items: center; gap: 18px; margin-top: 42px; color: #89938b; font-size: 12px; }
.hero-trust .avatars { display: flex; }
.hero-trust .avatars span {
    width: 31px; height: 31px; border-radius: 50%; border: 2px solid var(--site-ink);
    background: linear-gradient(145deg, #ddcba9, #6e7a62); margin-left: -8px;
}
.hero-trust .avatars span:first-child { margin-left: 0; background: linear-gradient(145deg, #d7b9a6, #8e5a74); }
.hero-trust .avatars span:nth-child(3) { background: linear-gradient(145deg, #c8c9ca, #394a5d); }
.hero-trust b { color: var(--site-cream); font-weight: 600; }

.hero-stack { position: relative; min-height: 600px; display: grid; place-items: center; }
.hero-stack:before {
    content: ''; position: absolute; inset: 8% 4%; border: 1px solid rgba(199,161,90,.18);
    border-radius: 50%; transform: rotate(-12deg);
}
.hero-stack:after {
    content: '8'; position: absolute; right: 2%; bottom: 2%; font-family: var(--font-display);
    font-size: 190px; line-height: 1; color: transparent; -webkit-text-stroke: 1px rgba(199,161,90,.18);
    pointer-events: none;
}
.hero-frame {
    position: relative; z-index: 2; width: 310px; aspect-ratio: 9 / 16;
    border-radius: 32px; overflow: hidden; border: 1px solid rgba(199,161,90,.45);
    box-shadow: 0 40px 90px rgba(0,0,0,.55); background: #f5f1e7;
