155:                 continue;
156:             }
157:             $rows[] = [
158:                 'name' => mb_substr($name, 0, 100),
159:                 'phone' => $this->cell($line, $map, 'phone'),
160:                 'group_name' => $this->cell($line, $map, 'group'),
161:                 'max_pax' => max(1, min(20, (int) ($this->cell($line, $map, 'pax') ?: 2))),
