229:             'name' => ['nama', 'name', 'tamu', 'nama_tamu'],
230:             'phone' => ['telepon', 'phone', 'whatsapp', 'no_hp', 'nomor', 'hp'],
231:             'group' => ['grup', 'group', 'kategori', 'kelompok'],
232:             'pax' => ['kuota', 'pax', 'jumlah', 'jumlah_tamu', 'max_pax'],
233:         ];
234:         $map = [];
235:         foreach ($header as $i => $value) {
236:             $key = strtolower(trim((string) $value));
237:             $key = str_replace([' ', '-'], '_', $key);
238:             foreach ($aliases as $target => $names) {
239:                 if (in_array($key, $names, true)) {
240:                     $map[$target] = $i;
241:                 }
242:             }
243:         }
244: 
245:         return $map;
246:     }
