116:         if ($name === '') {
117:             return back()->withErrors(['name' => 'Nama wajib diisi.'])->withInput();
118:         }
119: 
120:         $status = WeddingSetting::get('wish_moderation', 'post') === 'pre' ? 'hidden' : 'approved';
121: 
122:         $wedding->wishes()->create([
123:             'wedding_guest_id' => $guest?->id,
124:             'name' => $name,
