/* =====================================================================
   MELATI — Classic Floral Wedding
   Kertas gading, tinta hangat, emas tua, ornamen melati.
   ===================================================================== */

.tpl-melati {
    --bg: #fbf6ea;
    --paper: #fbf6ea;
    --paper-2: #f4ecda;
    --card: #fffdf7;
    --ink: #3b3225;
    --ink-soft: #5b4f3c;
    --muted: #8d7d62;
    --accent: #a8843b;
    --accent-2: #d8bf8a;
    --accent-soft: rgba(168, 132, 59, .10);
    --line: rgba(168, 132, 59, .26);
    --field-bg: rgba(255, 253, 247, .6);
    --field-radius: 2px;
    --btn-ink: #fffdf7;
    --btn-radius: 2px;
    --dock-bg: rgba(43, 36, 25, .86);
    --dock-ink: #f6ecd8;
    --display: 'Cormorant Garamond', 'Times New Roman', Georgia, serif;
    --script: 'Great Vibes', 'Cormorant Garamond', cursive;
    --body: 'DM Sans', ui-sans-serif, system-ui, sans-serif;
    background-color: var(--bg);
    color: var(--ink);
}

.tpl-melati ::selection { background: var(--accent); color: #fffdf7; }

.tpl-melati .tpl-main {
    background:
        radial-gradient(1200px 600px at 50% -100px, rgba(216, 191, 138, .22), transparent 70%),
        radial-gradient(900px 500px at -10% 40%, rgba(168, 132, 59, .07), transparent 65%),
        linear-gradient(180deg, #fbf6ea, #f8f1e1 45%, #fbf6ea);
    overflow: hidden;
}

.tpl-melati .tpl-kicker { color: var(--accent); }
.tpl-melati .tpl-title {
    font-family: var(--display);
    font-size: clamp(2.15rem, 5.4vw, 3.4rem);
    font-weight: 400;
    letter-spacing: .015em;
    color: var(--ink);
}
.tpl-melati .tpl-rule {
    position: relative;
    width: 120px;
    height: 1px;
    margin: 26px auto;
    background: linear-gradient(90deg, transparent, var(--accent-2), transparent);
    opacity: 1;
}
.tpl-melati .tpl-rule::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 7px;
    height: 7px;
    border: 1px solid var(--accent);
    transform: translate(-50%, -50%) rotate(45deg);
    background: var(--bg);
}

/* ---------------------------------------------------------------------
   Cover
   --------------------------------------------------------------------- */
.tpl-melati .mel-cover { background: #221b12; color: #fbf6ea; }

.tpl-melati .mel-cover-media img {
    object-position: center 32%;
    transform: scale(1.04);
    filter: saturate(.82) contrast(1.02);
}

.tpl-melati .mel-cover-veil {
    position: absolute;
    inset: 0;
    z-index: 1;
    background:
        radial-gradient(120% 70% at 50% 42%, rgba(20, 15, 8, .10), rgba(20, 15, 8, .56) 78%),
        linear-gradient(180deg, rgba(20, 15, 8, .55), rgba(20, 15, 8, .18) 38%, rgba(20, 15, 8, .64));
}

.tpl-melati .mel-cover-frame {
    width: min(540px, 100%);
    padding: clamp(28px, 6vw, 54px) clamp(20px, 5vw, 46px);
    border: 1px solid rgba(246, 236, 216, .62);
    outline: 1px solid rgba(246, 236, 216, .24);
    outline-offset: 9px;
    background: rgba(27, 21, 13, .20);
    backdrop-filter: blur(2.5px);
    -webkit-backdrop-filter: blur(2.5px);
    color: #fbf6ea;
    text-align: center;
}

.tpl-melati .mel-frame-corner {
    position: absolute;
    width: 26px;
    height: 26px;
    border-color: rgba(246, 236, 216, .86);
}
.tpl-melati .mel-frame-corner.tl { top: 7px; left: 7px; border-top: 1px solid; border-left: 1px solid; }
.tpl-melati .mel-frame-corner.tr { top: 7px; right: 7px; border-top: 1px solid; border-right: 1px solid; }
.tpl-melati .mel-frame-corner.bl { bottom: 7px; left: 7px; border-bottom: 1px solid; border-left: 1px solid; }
.tpl-melati .mel-frame-corner.br { bottom: 7px; right: 7px; border-bottom: 1px solid; border-right: 1px solid; }

.tpl-melati .mel-floral {
    position: absolute;
    z-index: 2;
    width: clamp(90px, 18vw, 150px);
    color: rgba(246, 236, 216, .42);
    pointer-events: none;
}
.tpl-melati .mel-floral svg { width: 100%; height: auto; }
.tpl-melati .mel-floral-tl { top: 0; left: 0; }
.tpl-melati .mel-floral-br { right: 0; bottom: 0; transform: rotate(180deg); }

.tpl-melati .mel-cover-eyebrow {
    margin: 0;
    font-family: var(--body);
    font-size: clamp(.52rem, 1.4vw, .64rem);
    font-weight: 500;
    letter-spacing: .42em;
    text-transform: uppercase;
    color: rgba(251, 246, 234, .82);
}

.tpl-melati .mel-cover-ornament {
    margin: 12px 0 4px;
    font-size: 1rem;
    color: #e0c793;
    letter-spacing: .2em;
}

.tpl-melati .mel-cover-names {
    margin: 0;
    font-family: var(--script);
    font-weight: 400;
    font-size: clamp(2.85rem, 10.5vw, 4.9rem);
    line-height: 1.02;
    letter-spacing: .01em;
    color: #fdf8ee;
    text-shadow: 0 2px 22px rgba(0, 0, 0, .28);
}
.tpl-melati .mel-cover-names span { display: block; }
.tpl-melati .mel-cover-names em {
    display: block;
    margin: .02em 0;
    font-family: var(--display);
    font-style: italic;
    font-size: .44em;
    font-weight: 300;
    color: #dfc38b;
}

.tpl-melati .mel-cover-date {
    margin: 18px 0 0;
    padding-top: 16px;
    border-top: 1px solid rgba(246, 236, 216, .32);
    font-family: var(--body);
    font-size: clamp(.6rem, 1.7vw, .72rem);
    letter-spacing: .38em;
    text-transform: uppercase;
    color: rgba(251, 246, 234, .9);
}

.tpl-melati .mel-guest { margin-top: 22px; color: rgba(251, 246, 234, .88); }
.tpl-melati .mel-guest span { color: rgba(251, 246, 234, .6); }
.tpl-melati .mel-guest strong {
    font-family: var(--display);
    font-size: clamp(1.1rem, 3.4vw, 1.4rem);
    color: #fdf8ee;
}

.tpl-melati .mel-open {
    margin-top: 24px;
    background: #fbf6ea;
    border-color: #fbf6ea;
    color: #4a3b22;
    box-shadow: 0 16px 36px rgba(0, 0, 0, .28);
}
.tpl-melati .mel-open:hover { background: #fffdf7; }

.tpl-melati .mel-cover-scroll {
    color: rgba(251, 246, 234, .55);
    font-size: .52rem;
}

/* ---------------------------------------------------------------------
   Hero / pembukaan
   --------------------------------------------------------------------- */
.tpl-melati .mel-hero {
    position: relative;
    display: grid;
    place-items: center;
    min-height: 82vh;
    padding: clamp(90px, 13vw, 150px) 24px clamp(70px, 9vw, 110px);
    text-align: center;
}
.tpl-melati .mel-hero::before,
.tpl-melati .mel-hero::after {
    content: '';
    position: absolute;
    width: 1px;
    height: 54px;
    background: linear-gradient(180deg, transparent, var(--accent-2));
    left: 50%;
}
.tpl-melati .mel-hero::before { top: 34px; }
.tpl-melati .mel-hero::after { bottom: 26px; transform: rotate(180deg); }

.tpl-melati .mel-hero-inner { width: min(720px, 100%); }
.tpl-melati .mel-arabic {
    margin: 0 0 18px;
    font-family: 'Traditional Arabic', 'Scheherazade New', 'Amiri', serif;
    font-size: clamp(1.35rem, 4vw, 1.9rem);
    color: var(--accent);
    line-height: 1.9;
}
.tpl-melati .mel-eyebrow {
    margin: 0;
    font-family: var(--body);
    font-size: .64rem;
    font-weight: 500;
    letter-spacing: .34em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-melati .mel-hero-text {
    margin: 26px auto 0;
    max-width: 580px;
    font-family: var(--display);
    font-size: clamp(1.02rem, 2.4vw, 1.18rem);
    line-height: 1.9;
    color: var(--ink-soft);
}
.tpl-melati .mel-hero-label {
    margin: 8px 0 0;
    font-family: var(--body);
    font-size: .6rem;
    letter-spacing: .3em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-melati .mel-hero-names {
    margin: 14px 0 0;
    font-family: var(--script);
    font-size: clamp(2.6rem, 8vw, 4.2rem);
    font-weight: 400;
    line-height: 1.08;
    color: var(--ink);
}
.tpl-melati .mel-hero-names em {
    font-family: var(--display);
    font-style: italic;
    color: var(--accent);
    font-size: .72em;
}
.tpl-melati .mel-hero-date {
    margin: 12px 0 0;
    font-family: var(--body);
    font-size: .68rem;
    letter-spacing: .3em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-melati .mel-scroll-hint {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    margin-top: 38px;
    font-family: var(--body);
    font-size: .56rem;
    letter-spacing: .26em;
    text-transform: uppercase;
    color: var(--accent);
    text-decoration: none;
}
.tpl-melati .mel-scroll-hint .tpl-icon { width: 16px; height: 16px; animation: mel-bob 2.4s ease-in-out infinite; }

@keyframes mel-bob {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(6px); }
}

/* ---------------------------------------------------------------------
   Section heading
   --------------------------------------------------------------------- */
.tpl-melati .mel-head { margin-bottom: clamp(36px, 6vw, 58px); }
.tpl-melati .mel-head .tpl-title { margin-top: 12px; }

/* ---------------------------------------------------------------------
   Couple
   --------------------------------------------------------------------- */
