    --field-bg: #fffdf9;
    --field-radius: 0px;
    --btn-ink: #f8f3ea;
    --btn-radius: 0px;
    --dock-bg: rgba(45, 42, 38, .92);
    --dock-ink: #f6f1e9;
    --display: 'Bodoni Moda', 'Times New Roman', Georgia, serif;
    --body: 'DM Sans', ui-sans-serif, system-ui, sans-serif;
    background: var(--bg);
    color: var(--ink);
    font-size: 15px;
}

.tpl-senja .tpl-main { overflow: hidden; }

.tpl-senja .sen-wrap {
    width: min(1120px, calc(100% - 48px));
    margin-inline: auto;
}

.tpl-senja .sen-label {
    display: inline-block;
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 600;
    letter-spacing: .32em;
    text-transform: uppercase;
    color: var(--muted);
}

.tpl-senja .sen-index {
    display: block;
    font-family: var(--display);
    font-size: .8rem;
    font-style: italic;
    color: var(--accent);
    letter-spacing: .04em;
}

.tpl-senja .sen-title {
    margin: 10px 0 0;
    font-family: var(--display);
    font-size: clamp(2.2rem, 5.6vw, 3.9rem);
    font-weight: 400;
    line-height: 1.02;
    letter-spacing: -.018em;
}

.tpl-senja .sen-title em {
    font-style: italic;
    font-weight: 400;
    color: var(--accent);
}

.tpl-senja .sen-link {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-family: var(--body);
    font-size: .7rem;
    font-weight: 600;
    letter-spacing: .08em;
    text-decoration: none;
    border-bottom: 1px solid var(--line);
    padding-bottom: 3px;
    transition: border-color .25s ease, color .25s ease;
}
.tpl-senja .sen-link:hover { border-color: var(--accent); color: var(--accent); }
.tpl-senja .sen-link .tpl-icon { width: 13px; height: 13px; }

/* ---------------------------------------------------------------------
   Cover
   --------------------------------------------------------------------- */
.tpl-senja .sen-cover { background: #1c1a17; color: #f9f5ee; }

.tpl-senja .sen-cover-media img {
    object-position: center 38%;
    filter: saturate(.78) contrast(1.02);
}

.tpl-senja .sen-cover-shade {
    position: absolute;
    inset: 0;
    z-index: 1;
    background:
        linear-gradient(180deg, rgba(18, 16, 13, .48), transparent 34%),
        linear-gradient(0deg, rgba(18, 16, 13, .86) 4%, rgba(18, 16, 13, .32) 46%, transparent 68%);
}

.tpl-senja .sen-cover-top {
    position: absolute;
    top: max(24px, env(safe-area-inset-top));
    left: 0;
    right: 0;
    z-index: 4;
    display: flex;
    justify-content: space-between;
    gap: 16px;
    padding-inline: clamp(20px, 5vw, 48px);
    font-family: var(--body);
    font-size: .56rem;
    font-weight: 500;
    letter-spacing: .26em;
    text-transform: uppercase;
    color: rgba(249, 245, 238, .78);
}

.tpl-senja .sen-cover-body {
    position: absolute;
    left: 0;
    bottom: 0;
    z-index: 4;
    width: 100%;
    padding: 0 clamp(20px, 6vw, 64px) clamp(50px, 9vw, 78px);
    text-align: left;
}

.tpl-senja .sen-cover-kicker {
    margin: 0 0 12px;
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 500;
    letter-spacing: .36em;
    text-transform: uppercase;
    color: rgba(249, 245, 238, .72);
}

.tpl-senja .sen-cover-names {
    margin: 0;
    font-family: var(--display);
    font-size: clamp(3rem, 12vw, 6.4rem);
    font-weight: 400;
    line-height: .86;
    letter-spacing: -.035em;
    color: #fbf7f0;
}
.tpl-senja .sen-cover-names span { display: block; }
.tpl-senja .sen-cover-names em {
    display: block;
    margin: .1em 0 .04em;
    font-size: .22em;
    font-style: italic;
    letter-spacing: .12em;
    color: var(--accent-2);
}

.tpl-senja .sen-cover-place {
    margin: 18px 0 0;
    font-family: var(--body);
    font-size: .6rem;
    font-weight: 500;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: rgba(249, 245, 238, .72);
}

.tpl-senja .sen-cover-footer {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
    margin-top: clamp(26px, 6vw, 44px);
    padding-top: 22px;
    border-top: 1px solid rgba(249, 245, 238, .26);
}

.tpl-senja .sen-guest { margin: 0; text-align: left; }
.tpl-senja .sen-guest span { color: rgba(249, 245, 238, .55); }
.tpl-senja .sen-guest strong {
    font-family: var(--display);
    font-size: clamp(1rem, 3.4vw, 1.35rem);
    font-style: italic;
    color: #fbf7f0;
}

.tpl-senja .sen-open {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    flex: none;
    padding: 14px 22px;
    border: 1px solid rgba(249, 245, 238, .55);
    border-radius: 0;
    background: transparent;
    color: #fbf7f0;
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 600;
    letter-spacing: .2em;
    text-transform: uppercase;
    transition: background .25s ease, color .25s ease;
}
.tpl-senja .sen-open:hover { background: #fbf7f0; color: #2d2a26; }
.tpl-senja .sen-open .tpl-icon { width: 14px; height: 14px; }

.tpl-senja .sen-cover-index {
    position: absolute;
    top: 15%;
    right: clamp(16px, 4vw, 40px);
    z-index: 3;
    font-family: var(--display);
    font-size: clamp(5rem, 18vw, 12rem);
    font-style: italic;
    line-height: 1;
    color: transparent;
    -webkit-text-stroke: 1px rgba(249, 245, 238, .25);
    pointer-events: none;
}

.tpl-senja .sen-cover-side {
    position: absolute;
    top: 50%;
    right: clamp(10px, 2.4vw, 20px);
    z-index: 3;
    transform: translateY(-50%) rotate(90deg);
    transform-origin: center;
    font-family: var(--body);
    font-size: .5rem;
    letter-spacing: .34em;
    text-transform: uppercase;
    color: rgba(249, 245, 238, .48);
    white-space: nowrap;
    pointer-events: none;
}

/* ---------------------------------------------------------------------
   Top bar
   --------------------------------------------------------------------- */
.tpl-senja .sen-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 16px clamp(20px, 5vw, 48px);
    border-bottom: 1px solid var(--line);
    font-family: var(--body);
    font-size: .56rem;
    font-weight: 600;
    letter-spacing: .24em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-senja .sen-topbar i { font-family: var(--display); font-style: italic; color: var(--accent); }

/* ---------------------------------------------------------------------
   Intro
   --------------------------------------------------------------------- */
.tpl-senja .sen-intro {
    padding: clamp(64px, 11vw, 130px) 0 0;
}
.tpl-senja .sen-intro-grid {
    display: grid;
    grid-template-columns: 130px minmax(0, 1fr);
    gap: clamp(20px, 4vw, 60px);
    align-items: start;
}
.tpl-senja .sen-intro-aside { display: grid; gap: 10px; padding-top: 6px; }
.tpl-senja .sen-intro-main { max-width: 780px; }
.tpl-senja .sen-lead {
    margin: 0;
    font-family: var(--display);
    font-size: clamp(1.12rem, 2.7vw, 1.5rem);
    font-weight: 400;
    line-height: 1.72;
    letter-spacing: -.005em;
    color: var(--ink-soft);
}
.tpl-senja .sen-intro-sign {
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: clamp(30px, 5vw, 48px);
}
.tpl-senja .sen-sign-names {
    font-family: var(--display);
    font-size: clamp(2rem, 5.2vw, 3.2rem);
    font-style: italic;
    line-height: 1;
}
.tpl-senja .sen-sign-amp {
    font-family: var(--body);
    font-size: .8rem;
    color: var(--accent);
    letter-spacing: .1em;
}

.tpl-senja .sen-marquee {
    margin-top: clamp(44px, 8vw, 90px);
    padding: 14px 0;
    border-block: 1px solid var(--line);
    overflow: hidden;
}
.tpl-senja .sen-marquee-track {
    display: flex;
    align-items: center;
    gap: 28px;
    width: max-content;
    animation: sen-marquee 34s linear infinite;
}
.tpl-senja .sen-marquee-track span {
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 600;
    letter-spacing: .32em;
    text-transform: uppercase;
    white-space: nowrap;
    color: var(--muted);
}
.tpl-senja .sen-marquee-track i { font-style: normal; color: var(--accent-2); font-size: .7rem; }

@keyframes sen-marquee {
    to { transform: translateX(-33.3333%); }
}

/* ---------------------------------------------------------------------
   Section head
   --------------------------------------------------------------------- */
.tpl-senja .sen-section-head {
    display: flex;
    gap: clamp(18px, 4vw, 46px);
    align-items: flex-start;
    padding-bottom: 26px;
    border-bottom: 1px solid var(--line);
}
.tpl-senja .sen-section-head .sen-index { padding-top: 8px; }

/* ---------------------------------------------------------------------
   Couple
   --------------------------------------------------------------------- */
.tpl-senja .sen-couple { padding: clamp(70px, 11vw, 130px) 0; }
.tpl-senja .sen-couple-grid {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: end;
    gap: clamp(18px, 4vw, 50px);
    margin-top: clamp(38px, 6vw, 64px);
}
.tpl-senja .sen-person { max-width: 380px; }
.tpl-senja .sen-person-right { justify-self: end; text-align: right; }
.tpl-senja .sen-person-photo {
    position: relative;
    margin: 0;
    overflow: hidden;
    background: var(--paper-2);
}
.tpl-senja .sen-person-photo img {
    width: 100%;
    aspect-ratio: 3 / 4;
    object-fit: cover;
    filter: saturate(.82) contrast(1.02);
    transition: transform 1s cubic-bezier(.2, .7, .2, 1);
}
.tpl-senja .sen-person:hover .sen-person-photo img { transform: scale(1.04); }
.tpl-senja .sen-person-photo figcaption {
    position: absolute;
    left: 14px;
    bottom: 14px;
    padding: 5px 10px;
    background: rgba(246, 241, 233, .86);
    font-family: var(--body);
    font-size: .5rem;
    font-weight: 600;
    letter-spacing: .26em;
    text-transform: uppercase;
}
.tpl-senja .sen-person h3 {
    margin: 22px 0 0;
    font-family: var(--display);
    font-size: clamp(1.6rem, 3.6vw, 2.2rem);
    font-weight: 400;
    line-height: 1.1;
}
.tpl-senja .sen-person-parent {
    margin: 8px 0 14px;
    font-size: .76rem;
    line-height: 1.75;
    color: var(--muted);
}
.tpl-senja .sen-couple-gap {
    display: grid;
    place-items: center;
    gap: 12px;
    padding-bottom: 90px;
}
.tpl-senja .sen-couple-gap span {
    font-family: var(--display);
    font-size: clamp(2.4rem, 6vw, 4rem);
    font-style: italic;
    color: var(--accent);
    line-height: 1;
}
.tpl-senja .sen-couple-gap small {
    font-family: var(--body);
    font-size: .48rem;
    letter-spacing: .26em;
    text-transform: uppercase;
    color: var(--muted);
    writing-mode: vertical-rl;
}

/* ---------------------------------------------------------------------
   Photo band
   --------------------------------------------------------------------- */
.tpl-senja .sen-band {
    position: relative;
    height: clamp(320px, 56vw, 620px);
    overflow: hidden;
    background: #26231f;
}
.tpl-senja .sen-band img {
    width: 100%;
    height: 118%;
    object-fit: cover;
    object-position: center 40%;
    filter: saturate(.78);
    will-change: transform;
}
.tpl-senja .sen-band::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(0deg, rgba(18, 16, 13, .62), transparent 50%);
}
.tpl-senja .sen-band span {
    position: absolute;
    left: clamp(20px, 5vw, 48px);
    bottom: 24px;
    z-index: 2;
    font-family: var(--body);
    font-size: .56rem;
    font-weight: 600;
    letter-spacing: .28em;
    text-transform: uppercase;
    color: rgba(249, 245, 238, .82);
}

/* ---------------------------------------------------------------------
   Quote (dark editorial)
   --------------------------------------------------------------------- */
.tpl-senja .sen-quote {
    padding: clamp(70px, 11vw, 130px) 0;
    background: #2d2a26;
    color: #f4efe6;
}
.tpl-senja .sen-quote-grid {
    display: grid;
    grid-template-columns: 130px minmax(0, 1fr);
    gap: clamp(20px, 4vw, 60px);
}
.tpl-senja .sen-quote .sen-index { color: var(--accent-2); }
.tpl-senja .sen-quote blockquote { margin: 0; max-width: 820px; }
.tpl-senja .sen-quote blockquote p {
    margin: 0;
    font-family: var(--display);
    font-size: clamp(1.3rem, 3.4vw, 2rem);
    font-style: italic;
    font-weight: 400;
    line-height: 1.55;
    letter-spacing: -.01em;
}
.tpl-senja .sen-quote cite {
    display: block;
    margin-top: 26px;
    font-family: var(--body);
    font-size: .56rem;
    font-style: normal;
    font-weight: 600;
    letter-spacing: .3em;
    text-transform: uppercase;
    color: var(--accent-2);
}

/* ---------------------------------------------------------------------
   Countdown
   --------------------------------------------------------------------- */
.tpl-senja .sen-countdown-section { padding: clamp(64px, 10vw, 118px) 0; }
.tpl-senja .sen-countdown-head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 16px;
    padding-bottom: 22px;
    border-bottom: 1px solid var(--line);
}
.tpl-senja .sen-countdown-head p {
    margin: 0;
    font-family: var(--body);
    font-size: .62rem;
    font-weight: 600;
    letter-spacing: .24em;
    text-transform: uppercase;
}
.tpl-senja .sen-countdown {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    margin-top: clamp(28px, 5vw, 46px);
}
.tpl-senja .sen-count {
    padding: 0 12px;
    border-left: 1px solid var(--line);
}
.tpl-senja .sen-count:first-child { border-left: 0; padding-left: 0; }
.tpl-senja .sen-count strong {
    display: block;
    font-family: var(--display);
    font-size: clamp(2.6rem, 8.4vw, 5.6rem);
    font-weight: 400;
    line-height: .95;
    letter-spacing: -.04em;
    font-variant-numeric: tabular-nums;
}
.tpl-senja .sen-count span {
    display: block;
    margin-top: 10px;
    font-family: var(--body);
    font-size: .5rem;
    font-weight: 600;
    letter-spacing: .28em;
    text-transform: uppercase;
    color: var(--muted);
}

/* ---------------------------------------------------------------------
   Events
   --------------------------------------------------------------------- */
.tpl-senja .sen-events {
    padding: clamp(70px, 11vw, 130px) 0;
    background: var(--card);
}
.tpl-senja .sen-event-list { margin-top: clamp(30px, 5vw, 50px); }
.tpl-senja .sen-event {
    display: grid;
    grid-template-columns: 46px 92px minmax(0, 1fr) auto;
    gap: clamp(14px, 3vw, 34px);
    align-items: start;
    padding: clamp(22px, 3.6vw, 34px) 0;
    border-top: 1px solid var(--line);
    transition: background .3s ease, padding .3s ease;
}
.tpl-senja .sen-event:last-child { border-bottom: 1px solid var(--line); }
.tpl-senja .sen-event:hover { background: rgba(183, 155, 128, .09); }
.tpl-senja .sen-event-number {
    font-family: var(--display);
    font-size: .78rem;
    font-style: italic;
    color: var(--accent);
    padding-top: 4px;
}
.tpl-senja .sen-event-date { padding-top: 2px; }
.tpl-senja .sen-event-date strong {
    display: block;
    font-family: var(--display);
    font-size: clamp(1.7rem, 4vw, 2.4rem);
    font-weight: 400;
    line-height: 1;
}
.tpl-senja .sen-event-date span {
    display: block;
    margin-top: 4px;
    font-family: var(--body);
    font-size: .54rem;
    font-weight: 600;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-senja .sen-event-body h3 {
    margin: 0;
    font-family: var(--display);
    font-size: clamp(1.35rem, 3vw, 1.8rem);
    font-weight: 400;
}
.tpl-senja .sen-event-time {
    margin: 5px 0 0;
    font-size: .62rem;
    font-weight: 600;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-senja .sen-event-venue { margin: 12px 0 0; font-size: .88rem; font-weight: 500; }
.tpl-senja .sen-event-address { margin: 3px 0 0; font-size: .78rem; line-height: 1.7; color: var(--muted); }
.tpl-senja .sen-map {
    display: grid;
    justify-items: center;
    gap: 5px;
    color: var(--muted);
    text-decoration: none;
    padding-top: 4px;
    transition: color .25s ease;
}
.tpl-senja .sen-map:hover { color: var(--accent); }
.tpl-senja .sen-map .tpl-icon { width: 20px; height: 20px; }
.tpl-senja .sen-map span { font-family: var(--body); font-size: .46rem; letter-spacing: .2em; text-transform: uppercase; }

.tpl-senja .sen-live {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    flex-wrap: wrap;
    margin-top: 36px;
}

/* ---------------------------------------------------------------------
   Story
   --------------------------------------------------------------------- */
.tpl-senja .sen-story { padding: clamp(70px, 11vw, 130px) 0; }
.tpl-senja .sen-story-list { margin-top: 20px; }
.tpl-senja .sen-story-item {
    display: grid;
    grid-template-columns: 150px minmax(0, 1fr);
    gap: clamp(18px, 4vw, 46px);
    padding: 26px 0;
    border-bottom: 1px solid var(--line);
}
.tpl-senja .sen-story-item:first-child { border-top: 1px solid var(--line); }
.tpl-senja .sen-story-year {
    font-family: var(--display);
    font-size: 1.4rem;
    font-style: italic;
    color: var(--accent);
}
.tpl-senja .sen-story-item h3 {
    margin: 0;
    font-family: var(--display);
    font-size: 1.5rem;
    font-weight: 400;
}
.tpl-senja .sen-story-item p {
    margin: 7px 0 0;
    max-width: 700px;
    font-size: .86rem;
    line-height: 1.8;
    color: var(--muted);
}

/* ---------------------------------------------------------------------
   Gallery
   --------------------------------------------------------------------- */
.tpl-senja .sen-gallery {
    padding: clamp(70px, 11vw, 130px) 0;
    background: var(--paper-2);
}
.tpl-senja .sen-gallery-head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 24px;
    margin-bottom: clamp(28px, 4vw, 44px);
}
.tpl-senja .sen-gallery-head .sen-label { display: block; margin-top: 8px; }
.tpl-senja .sen-slider-nav { display: flex; gap: 8px; }
.tpl-senja .sen-slider-nav button {
    display: grid;
    place-items: center;
    width: 46px;
    height: 46px;
    border: 1px solid var(--line);
    border-radius: 50%;
    background: transparent;
    color: var(--ink);
    transition: background .25s ease, color .25s ease;
}
.tpl-senja .sen-slider-nav button:hover { background: var(--ink); color: var(--paper); }
.tpl-senja .sen-gallery-track {
    display: flex;
    gap: 14px;
    overflow-x: auto;
    padding: 4px max(24px, calc((100vw - 1120px) / 2)) 22px;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
}
.tpl-senja .sen-gallery-track::-webkit-scrollbar { display: none; }
.tpl-senja .sen-photo {
    position: relative;
    flex: 0 0 clamp(230px, 34vw, 400px);
    padding: 0;
    border: 0;
    background: #ded3c2;
    overflow: hidden;
    scroll-snap-align: start;
    cursor: zoom-in;
}
.tpl-senja .sen-photo img {
    width: 100%;
    aspect-ratio: 4 / 5;
    object-fit: cover;
    filter: saturate(.82);
    transition: transform .9s cubic-bezier(.2, .7, .2, 1);
}
.tpl-senja .sen-photo.is-tall img { aspect-ratio: 3 / 4.4; }
.tpl-senja .sen-photo:hover img { transform: scale(1.05); }
.tpl-senja .sen-photo span {
    position: absolute;
    left: 12px;
    top: 12px;
    font-family: var(--display);
    font-size: .76rem;
    font-style: italic;
    color: #fff;
    text-shadow: 0 1px 10px rgba(0, 0, 0, .4);
}
.tpl-senja .sen-hashtag {
    margin: 22px 0 0;
    font-family: var(--display);
    font-size: clamp(1.4rem, 3.6vw, 2.1rem);
    font-style: italic;
    color: var(--ink-soft);
}

/* ---------------------------------------------------------------------
   Gifts
   --------------------------------------------------------------------- */
.tpl-senja .sen-gifts { padding: clamp(70px, 11vw, 130px) 0; }
.tpl-senja .sen-gift-lead {
    max-width: 560px;
    margin: 30px 0 0;
    font-size: .86rem;
    line-height: 1.85;
    color: var(--muted);
}
.tpl-senja .sen-gift-list { margin-top: 34px; }
.tpl-senja .sen-gift {
    display: grid;
    grid-template-columns: 150px minmax(0, 1fr) 180px auto;
    gap: clamp(12px, 3vw, 26px);
    align-items: center;
    padding: 22px 0;
    border-top: 1px solid var(--line);
}
.tpl-senja .sen-gift:last-child { border-bottom: 1px solid var(--line); }
.tpl-senja .sen-gift-bank {
    font-family: var(--body);
    font-size: .6rem;
    font-weight: 700;
    letter-spacing: .22em;
