    margin-inline: auto;
}
.tpl-senja .sen-closing-top .sen-label { color: var(--accent-2); }
.tpl-senja .sen-closing-top p {
    margin: 20px 0 0;
    font-family: var(--display);
    font-size: clamp(1rem, 2.4vw, 1.2rem);
    font-style: italic;
    line-height: 1.8;
    color: rgba(244, 239, 230, .86);
}
.tpl-senja .sen-closing-names {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: center;
    gap: 14px;
    margin: clamp(40px, 7vw, 70px) 0 0;
    font-family: var(--display);
    font-size: clamp(2.6rem, 10vw, 6.5rem);
    font-weight: 400;
    line-height: .9;
    letter-spacing: -.035em;
}
.tpl-senja .sen-closing-names em { font-size: .3em; color: var(--accent-2); }
.tpl-senja .sen-closing-meta {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 12px 28px;
    margin-top: 24px;
    font-family: var(--body);
    font-size: .56rem;
    font-weight: 600;
    letter-spacing: .24em;
    text-transform: uppercase;
    color: rgba(244, 239, 230, .56);
}
.tpl-senja .sen-closing-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 10px;
    margin-top: 36px;
}
.tpl-senja .sen-open-dark { background: #f4efe6; color: #26231f; border-color: #f4efe6; }
.tpl-senja .sen-open-dark:hover { background: transparent; color: #f4efe6; }
.tpl-senja .sen-open-ghost { border-color: rgba(244, 239, 230, .35); }
.tpl-senja .sen-credit {
    margin: 54px 0 0;
    font-family: var(--body);
    font-size: .54rem;
    letter-spacing: .18em;
    text-transform: uppercase;
    color: rgba(244, 239, 230, .4);
}

/* ---------------------------------------------------------------------
   Responsive
   --------------------------------------------------------------------- */
@media (max-width: 900px) {
    .tpl-senja .sen-intro-grid,
    .tpl-senja .sen-quote-grid { grid-template-columns: 1fr; gap: 16px; }
    .tpl-senja .sen-intro-aside { display: flex; align-items: center; gap: 12px; }
    .tpl-senja .sen-couple-grid { grid-template-columns: 1fr; gap: 34px; }
    .tpl-senja .sen-person,
    .tpl-senja .sen-person-right { max-width: 440px; justify-self: start; text-align: left; margin-inline: auto; }
    .tpl-senja .sen-couple-gap { padding: 0; }
    .tpl-senja .sen-couple-gap small { writing-mode: horizontal-tb; }
    .tpl-senja .sen-event { grid-template-columns: 34px 70px minmax(0, 1fr); }
    .tpl-senja .sen-map { grid-column: 3; grid-auto-flow: column; justify-self: start; align-items: center; gap: 6px; }
    .tpl-senja .sen-gift { grid-template-columns: 1fr auto; }
    .tpl-senja .sen-gift-bank { grid-column: 1 / -1; }
    .tpl-senja .sen-gift-copy { grid-row: 2 / 4; }
    .tpl-senja .sen-rsvp-grid,
    .tpl-senja .sen-wishes-grid { grid-template-columns: 1fr; }
}

@media (max-width: 620px) {
    .tpl-senja .sen-wrap { width: calc(100% - 36px); }
    .tpl-senja .sen-cover-index { top: 11%; font-size: 7rem; }
    .tpl-senja .sen-cover-side { display: none; }
    .tpl-senja .sen-cover-footer { flex-direction: column; align-items: flex-start; }
    .tpl-senja .sen-cover-body { padding-bottom: 46px; }
    .tpl-senja .sen-countdown { grid-template-columns: repeat(2, 1fr); gap: 26px 0; }
    .tpl-senja .sen-count:nth-child(3) { border-left: 0; padding-left: 0; }
    .tpl-senja .sen-event { grid-template-columns: 30px minmax(0, 1fr); }
    .tpl-senja .sen-event-date { grid-column: 2; display: flex; align-items: baseline; gap: 8px; }
    .tpl-senja .sen-event-body { grid-column: 2; }
    .tpl-senja .sen-map { grid-column: 2; }
    .tpl-senja .sen-story-item { grid-template-columns: 1fr; gap: 6px; }
    .tpl-senja .sen-photo { flex-basis: 76vw; }
    .tpl-senja .sen-gallery-track { padding-inline: 18px; }
}

