/* SENJA — parallax pita foto dan galeri geser (drag) ala majalah. */
(function () {
    'use strict';

    if (!document.body.classList.contains('tpl-senja')) return;

    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* Parallax pita foto */
    var band = document.querySelector('.sen-band');
    var bandImage = band ? band.querySelector('img') : null;

    if (band && bandImage && !reduceMotion) {
        var ticking = false;

        function parallax() {
            var rect = band.getBoundingClientRect();
            if (rect.bottom > 0 && rect.top < window.innerHeight) {
                var progress = (rect.top + rect.height / 2 - window.innerHeight / 2) / window.innerHeight;
                bandImage.style.transform = 'translate3d(0,' + (progress * -34).toFixed(2) + 'px,0)';
            }
            ticking = false;
        }

        window.addEventListener('scroll', function () {
            if (ticking) return;
            ticking = true;
            window.requestAnimationFrame(parallax);
        }, { passive: true });

        parallax();
    }

    /* Galeri bisa digeser dengan mouse */
    var track = document.querySelector('.sen-gallery-track');

    if (track && window.matchMedia('(pointer: fine)').matches) {
        var down = false;
        var startX = 0;
        var startScroll = 0;
        var moved = false;

        track.addEventListener('pointerdown', function (event) {
            down = true;
            moved = false;
            startX = event.clientX;
            startScroll = track.scrollLeft;
            track.setPointerCapture(event.pointerId);
        });

        track.addEventListener('pointermove', function (event) {
            if (!down) return;
            var delta = event.clientX - startX;
            if (Math.abs(delta) > 4) moved = true;
            track.scrollLeft = startScroll - delta;
        });

        track.addEventListener('pointerup', function (event) {
            down = false;
            try { track.releasePointerCapture(event.pointerId); } catch (error) { /* abaikan */ }
        });

        track.addEventListener('pointercancel', function () { down = false; });

        track.addEventListener('click', function (event) {
            if (moved) {
                event.preventDefault();
                event.stopPropagation();
                moved = false;
            }
        }, true);
    }
})();

/* =====================================================================
   LESTARI — Botanical Garden Wedding
   Lengkung arsitektural, sage, kertas alami, ilustrasi daun.
   ===================================================================== */

.tpl-lestari {
    --bg: #f7f3e9;
    --paper: #f7f3e9;
    --paper-2: #eef0e6;
    --card: #fffdf7;
    --ink: #2f362a;
    --ink-soft: #4a5343;
    --muted: #7d8775;
    --accent: #65704f;
    --accent-2: #9caa8f;
    --accent-soft: rgba(101, 112, 79, .12);
    --line: rgba(101, 112, 79, .24);
    --field-bg: #fffdf8;
    --field-radius: 14px;
    --btn-ink: #fbf8f0;
    --btn-radius: 999px;
    --dock-bg: rgba(47, 54, 42, .9);
    --dock-ink: #f3f0e4;
    --display: 'Fraunces', 'Iowan Old Style', Georgia, serif;
    --body: 'DM Sans', ui-sans-serif, system-ui, sans-serif;
    background: var(--bg);
    color: var(--ink);
}

.tpl-lestari .tpl-main { overflow: hidden; }

.tpl-lestari .les-wrap {
    width: min(1100px, calc(100% - 44px));
    margin-inline: auto;
}

.tpl-lestari .les-kicker {
    display: inline-block;
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 600;
    letter-spacing: .3em;
    text-transform: uppercase;
    color: var(--accent);
}

.tpl-lestari .les-head { margin-bottom: clamp(34px, 5vw, 54px); }
.tpl-lestari .les-head h2 {
    margin: 12px 0 0;
    font-family: var(--display);
    font-size: clamp(2rem, 5vw, 3.2rem);
    font-weight: 400;
    font-variation-settings: 'SOFT' 30, 'WONK' 0;
    line-height: 1.1;
    letter-spacing: -.015em;
}
.tpl-lestari .les-head-center { text-align: center; }
.tpl-lestari .les-head-center h2 { margin-inline: auto; max-width: 620px; }

.tpl-lestari .les-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 11px 20px;
    border: 1px solid var(--accent);
    border-radius: 999px;
    background: transparent;
    color: var(--accent);
    font-family: var(--body);
    font-size: .62rem;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    text-decoration: none;
    transition: background .25s ease, color .25s ease, transform .25s ease;
}
.tpl-lestari .les-btn:hover { background: var(--accent); color: var(--btn-ink); transform: translateY(-1px); }
.tpl-lestari .les-btn .tpl-icon { width: 15px; height: 15px; }

/* ---------------------------------------------------------------------
   Cover
   --------------------------------------------------------------------- */
.tpl-lestari .les-cover { background: var(--bg); overflow-y: auto; }

.tpl-lestari .les-cover::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
        radial-gradient(600px 320px at 50% 12%, rgba(156, 170, 143, .26), transparent 70%),
        radial-gradient(400px 300px at 88% 80%, rgba(101, 112, 79, .10), transparent 70%),
        linear-gradient(180deg, #f8f4ea, #f2efe2);
}

.tpl-lestari .les-cover-leaf {
    position: absolute;
    z-index: 1;
    width: clamp(110px, 24vw, 190px);
    color: rgba(101, 112, 79, .28);
    pointer-events: none;
}
.tpl-lestari .les-cover-leaf svg { width: 100%; height: auto; }
.tpl-lestari .les-leaf-a { left: -24px; bottom: -36px; }
.tpl-lestari .les-leaf-b { right: -28px; top: -30px; transform: rotate(180deg); }

.tpl-lestari .les-cover-inner {
    width: min(460px, 100%);
    color: var(--ink);
    text-align: center;
}

.tpl-lestari .les-kicker { color: var(--accent); }

.tpl-lestari .les-arch {
    position: relative;
    width: clamp(180px, 52vw, 264px);
    margin: clamp(18px, 3.4vw, 26px) auto 0;
    padding: 7px;
    border: 1px solid var(--accent-2);
    border-radius: 999px 999px 0 0;
    background: rgba(255, 253, 247, .5);
}
.tpl-lestari .les-arch-inner {
    overflow: hidden;
    border-radius: 999px 999px 0 0;
}
.tpl-lestari .les-arch img {
    width: 100%;
    aspect-ratio: 3 / 4;
    object-fit: cover;
    filter: saturate(.86);
}
.tpl-lestari .les-arch-leaves {
    position: absolute;
    top: -24px;
    left: 50%;
    transform: translateX(-50%);
    width: 96px;
    color: var(--accent);
    background: var(--bg);
    padding: 0 8px;
}
.tpl-lestari .les-arch-leaves svg { width: 100%; height: auto; }

.tpl-lestari .les-cover-names {
    margin: clamp(22px, 4vw, 30px) 0 0;
    font-family: var(--display);
    font-size: clamp(2rem, 6.4vw, 3.1rem);
    font-weight: 400;
    font-variation-settings: 'SOFT' 50;
    line-height: 1.08;
    letter-spacing: -.02em;
}
.tpl-lestari .les-cover-names span {
    display: inline-block;
    margin: 0 .1em;
    font-size: .52em;
    font-style: italic;
    color: var(--accent);
}
.tpl-lestari .les-cover-date {
    margin: 12px 0 0;
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 600;
    letter-spacing: .3em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-lestari .les-guest { margin-top: 18px; color: var(--ink); }
.tpl-lestari .les-guest span { color: var(--muted); }
.tpl-lestari .les-guest strong { color: var(--accent); }
.tpl-lestari .les-open { margin-top: 20px; background: var(--accent); border-color: var(--accent); color: var(--btn-ink); }

.tpl-lestari .les-cover-foot {
    position: absolute;
    bottom: max(16px, env(safe-area-inset-bottom));
    left: 50%;
    transform: translateX(-50%);
    z-index: 2;
    font-family: var(--body);
    font-size: .48rem;
    letter-spacing: .32em;
    text-transform: uppercase;
    color: var(--muted);
    white-space: nowrap;
}

/* ---------------------------------------------------------------------
   Hero
   --------------------------------------------------------------------- */
.tpl-lestari .les-hero {
    position: relative;
    padding: clamp(64px, 10vw, 110px) 0 clamp(70px, 10vw, 120px);
    text-align: center;
    background:
        radial-gradient(700px 420px at 50% 0, rgba(156, 170, 143, .24), transparent 70%);
}
.tpl-lestari .les-monogram {
    display: inline-grid;
    place-items: center;
    width: 78px;
    height: 78px;
    border: 1px solid var(--accent);
    border-radius: 50%;
    font-family: var(--display);
    font-size: 1.25rem;
    letter-spacing: .02em;
    color: var(--accent);
    position: relative;
}
.tpl-lestari .les-monogram::after {
    content: '';
    position: absolute;
    inset: 5px;
    border: 1px solid rgba(101, 112, 79, .28);
    border-radius: 50%;
}
.tpl-lestari .les-monogram i { font-size: .7em; font-style: italic; opacity: .7; }
.tpl-lestari .les-hero-kicker {
    margin: 24px 0 0;
    font-family: var(--body);
    font-size: .6rem;
    font-weight: 600;
    letter-spacing: .32em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-lestari .les-hero-names {
    margin: 16px 0 0;
    font-family: var(--display);
    font-size: clamp(2.5rem, 8vw, 4.4rem);
    font-weight: 400;
    font-variation-settings: 'SOFT' 40;
    line-height: 1.04;
    letter-spacing: -.025em;
}
.tpl-lestari .les-hero-names em {
    font-style: italic;
    font-size: .6em;
    color: var(--accent);
}
.tpl-lestari .les-hero-date {
    margin: 14px 0 0;
    font-family: var(--body);
    font-size: .62rem;
    font-weight: 600;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-lestari .les-leaf-rule {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin: 28px auto;
    color: var(--accent-2);
}
.tpl-lestari .les-leaf-rule span { display: block; width: 48px; height: 1px; background: var(--accent-2); }
.tpl-lestari .les-leaf-rule svg { width: 34px; height: 22px; }
.tpl-lestari .les-hero-text {
    max-width: 640px;
    margin-inline: auto;
    font-family: var(--display);
    font-size: clamp(1rem, 2.3vw, 1.14rem);
    font-weight: 300;
    line-height: 1.9;
    color: var(--ink-soft);
}
.tpl-lestari .les-scroll {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    gap: 7px;
    margin-top: 40px;
    font-family: var(--body);
    font-size: .52rem;
    font-weight: 600;
    letter-spacing: .26em;
    text-transform: uppercase;
    color: var(--accent);
    text-decoration: none;
}
.tpl-lestari .les-scroll .tpl-icon { width: 15px; height: 15px; animation: les-bob 3s ease-in-out infinite; }

@keyframes les-bob {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(7px); }
}

/* ---------------------------------------------------------------------
   Couple
   --------------------------------------------------------------------- */
.tpl-lestari .les-couple { padding: clamp(60px, 9vw, 100px) 0; background: var(--card); }
.tpl-lestari .les-couple-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: clamp(26px, 6vw, 70px);
    max-width: 820px;
    margin-inline: auto;
}
.tpl-lestari .les-person { text-align: center; }
.tpl-lestari .les-portrait {
    position: relative;
    overflow: hidden;
    border-radius: 999px 999px 18px 18px;
    border: 1px solid var(--accent-2);
    padding: 7px;
    background: var(--bg);
}
.tpl-lestari .les-portrait img {
    width: 100%;
    aspect-ratio: 3 / 4;
    object-fit: cover;
    border-radius: 999px 999px 12px 12px;
    filter: saturate(.85);
    transition: transform .9s cubic-bezier(.2, .7, .2, 1);
}
.tpl-lestari .les-person:hover img { transform: scale(1.04); }
.tpl-lestari .les-badge {
    position: absolute;
    left: 50%;
    bottom: 16px;
    transform: translateX(-50%);
    padding: 6px 14px;
    border-radius: 999px;
    background: rgba(247, 243, 233, .92);
    font-family: var(--body);
    font-size: .5rem;
    font-weight: 700;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-lestari .les-person h3 {
    margin: 20px 0 0;
    font-family: var(--display);
    font-size: clamp(1.5rem, 3.4vw, 2rem);
    font-weight: 450;
}
.tpl-lestari .les-parents {
    margin: 6px auto 0;
    max-width: 280px;
    font-size: .78rem;
    line-height: 1.75;
    color: var(--muted);
}
.tpl-lestari .les-social {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 10px;
    font-size: .68rem;
    color: var(--accent);
    text-decoration: none;
}
.tpl-lestari .les-social .tpl-icon { width: 13px; height: 13px; }

/* ---------------------------------------------------------------------
   Quote
   --------------------------------------------------------------------- */
.tpl-lestari .les-quote {
    position: relative;
    padding: clamp(64px, 10vw, 110px) 0;
    background: #4c5740;
    color: #f3f0e4;
    overflow: hidden;
}
.tpl-lestari .les-quote::before,
.tpl-lestari .les-quote::after {
    content: '';
    position: absolute;
    width: 260px;
    height: 260px;
    border: 1px solid rgba(243, 240, 228, .14);
    border-radius: 50%;
}
.tpl-lestari .les-quote::before { top: -120px; left: -80px; }
.tpl-lestari .les-quote::after { right: -100px; bottom: -140px; }
.tpl-lestari .les-quote-inner {
    position: relative;
    z-index: 2;
    max-width: 780px;
    text-align: center;
}
.tpl-lestari .les-quote-leaf { display: inline-block; width: 48px; color: var(--accent-2); }
.tpl-lestari .les-quote-leaf svg { width: 100%; height: auto; }
.tpl-lestari .les-quote blockquote {
    margin: 22px 0 0;
    font-family: var(--display);
    font-size: clamp(1.14rem, 2.9vw, 1.5rem);
    font-weight: 300;
    font-style: italic;
    line-height: 1.85;
    color: #f6f3e9;
}
.tpl-lestari .les-quote cite {
    display: block;
    margin-top: 20px;
    font-family: var(--body);
    font-size: .58rem;
    font-style: normal;
    font-weight: 600;
    letter-spacing: .28em;
    text-transform: uppercase;
    color: var(--accent-2);
}

/* ---------------------------------------------------------------------
   Countdown
   --------------------------------------------------------------------- */
.tpl-lestari .les-countdown-section { padding: clamp(64px, 9vw, 106px) 0; }
.tpl-lestari .les-countdown-date {
    margin: 14px 0 0;
    font-family: var(--body);
    font-size: .6rem;
    font-weight: 600;
    letter-spacing: .26em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-lestari .les-countdown {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: clamp(8px, 1.8vw, 16px);
    max-width: 690px;
    margin-inline: auto;
}
.tpl-lestari .les-count {
    position: relative;
    padding: clamp(20px, 3vw, 30px) 8px clamp(14px, 2.4vw, 20px);
    border: 1px solid var(--line);
    border-radius: 999px 999px 12px 12px;
    background: var(--card);
    text-align: center;
    overflow: hidden;
}
.tpl-lestari .les-count::before {
    content: '';
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 34px;
    height: 3px;
    border-radius: 999px;
    background: var(--accent-2);
}
.tpl-lestari .les-count strong {
    display: block;
    font-family: var(--display);
    font-size: clamp(1.7rem, 4.8vw, 2.7rem);
    font-weight: 400;
    line-height: 1;
    color: var(--accent);
    font-variant-numeric: tabular-nums;
}
.tpl-lestari .les-count span {
    display: block;
    margin-top: 9px;
    font-family: var(--body);
    font-size: .5rem;
    font-weight: 600;
    letter-spacing: .2em;
    text-transform: uppercase;
    color: var(--muted);
}

/* ---------------------------------------------------------------------
   Events
   --------------------------------------------------------------------- */
.tpl-lestari .les-events { padding: clamp(64px, 9vw, 106px) 0; background: var(--card); }
.tpl-lestari .les-event-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: clamp(18px, 3vw, 30px);
}
.tpl-lestari .les-event {
    display: grid;
    grid-template-columns: 128px minmax(0, 1fr);
    border: 1px solid var(--line);
    border-radius: 22px;
    overflow: hidden;
    background: var(--bg);
}
.tpl-lestari .les-event-arch {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    padding: 24px 12px;
    background: var(--paper-2);
    border-right: 1px solid var(--line);
    text-align: center;
}
.tpl-lestari .les-event-icon {
    display: grid;
    place-items: center;
    width: 38px;
    height: 38px;
    margin-bottom: 8px;
    border: 1px solid var(--accent-2);
    border-radius: 50%;
    color: var(--accent);
}
.tpl-lestari .les-event-icon .tpl-icon { width: 17px; height: 17px; }
.tpl-lestari .les-event-day {
    margin: 0;
    font-family: var(--display);
    font-size: 2.3rem;
    font-weight: 400;
    line-height: 1;
    color: var(--accent);
}
.tpl-lestari .les-event-month {
    margin: 4px 0 0;
    font-family: var(--body);
    font-size: .5rem;
    font-weight: 600;
    letter-spacing: .18em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-lestari .les-event-body { padding: clamp(20px, 3vw, 28px); }
.tpl-lestari .les-event-body h3 {
    margin: 0;
    font-family: var(--display);
    font-size: 1.4rem;
    font-weight: 450;
}
.tpl-lestari .les-event-time {
    margin: 4px 0 0;
    font-family: var(--body);
    font-size: .6rem;
    font-weight: 600;
    letter-spacing: .14em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-lestari .les-event-venue { margin: 12px 0 0; font-size: .86rem; font-weight: 500; }
.tpl-lestari .les-event-address { margin: 3px 0 14px; font-size: .76rem; line-height: 1.7; color: var(--muted); }
.tpl-lestari .les-live {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    flex-wrap: wrap;
    margin-top: 30px;
}

/* ---------------------------------------------------------------------
   Story
   --------------------------------------------------------------------- */
.tpl-lestari .les-story { padding: clamp(64px, 9vw, 106px) 0; }
.tpl-lestari .les-vine {
    position: relative;
    max-width: 640px;
    margin-inline: auto;
    padding-left: 44px;
}
.tpl-lestari .les-vine::before {
    content: '';
    position: absolute;
    top: 8px;
    bottom: 8px;
