}
.tpl-lestari .les-vine-item {
    position: relative;
    padding: 0 0 32px 18px;
}
.tpl-lestari .les-vine-item:last-child { padding-bottom: 0; }
.tpl-lestari .les-vine-dot {
    position: absolute;
    top: 4px;
    left: -39px;
    width: 16px;
    height: 16px;
    border-radius: 50% 50% 50% 0;
    background: var(--accent);
    transform: rotate(-45deg);
}
.tpl-lestari .les-vine-date {
    margin: 0;
    font-family: var(--body);
    font-size: .54rem;
    font-weight: 600;
    letter-spacing: .24em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-lestari .les-vine-item h3 {
    margin: 5px 0 0;
    font-family: var(--display);
    font-size: 1.35rem;
    font-weight: 450;
}
.tpl-lestari .les-vine-item p:last-child {
    margin: 6px 0 0;
    font-size: .84rem;
    line-height: 1.8;
    color: var(--muted);
}

/* ---------------------------------------------------------------------
   Gallery
   --------------------------------------------------------------------- */
.tpl-lestari .les-gallery-section { padding: clamp(64px, 9vw, 106px) 0; background: var(--card); }
.tpl-lestari .les-gallery {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-auto-rows: 180px;
    gap: 10px;
}
.tpl-lestari .les-photo {
    position: relative;
    overflow: hidden;
    padding: 0;
    border: 0;
    border-radius: 12px;
    background: var(--paper-2);
    cursor: zoom-in;
}
.tpl-lestari .les-photo.is-arch { border-radius: 999px 999px 12px 12px; grid-row: span 2; }
.tpl-lestari .les-photo.is-wide { grid-column: span 2; }
.tpl-lestari .les-photo img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: saturate(.86);
    transition: transform .9s cubic-bezier(.2, .7, .2, 1);
}
.tpl-lestari .les-photo:hover img { transform: scale(1.05); }
.tpl-lestari .les-hashtag {
    margin: 26px 0 0;
    font-family: var(--display);
    font-size: clamp(1.3rem, 3.4vw, 1.9rem);
    font-style: italic;
    text-align: center;
    color: var(--accent);
}

/* ---------------------------------------------------------------------
   Gifts
   --------------------------------------------------------------------- */
.tpl-lestari .les-gifts { padding: clamp(64px, 9vw, 106px) 0; }
.tpl-lestari .les-gift-lead {
    max-width: 540px;
    margin: 16px auto 0;
    font-size: .84rem;
    line-height: 1.8;
    color: var(--muted);
}
.tpl-lestari .les-gift-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18px;
    max-width: 760px;
    margin: 36px auto 0;
}
.tpl-lestari .les-gift {
    position: relative;
    padding: 28px 24px 24px;
    border: 1px solid var(--line);
    border-radius: 999px 999px 18px 18px;
    background: var(--card);
    text-align: center;
}
.tpl-lestari .les-gift-leaf { display: inline-block; width: 36px; color: var(--accent-2); }
.tpl-lestari .les-gift-leaf svg { width: 100%; height: auto; }
.tpl-lestari .les-gift-bank {
    display: block;
    margin-top: 8px;
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 700;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-lestari .les-gift-number {
    margin: 8px 0 0;
    font-family: var(--display);
    font-size: clamp(1.2rem, 3.2vw, 1.55rem);
    letter-spacing: .03em;
    word-break: break-all;
}
.tpl-lestari .les-gift-name { margin: 2px 0 14px; font-size: .72rem; color: var(--muted); }
.tpl-lestari .les-copy { width: 100%; }

/* ---------------------------------------------------------------------
   RSVP / wishes
   --------------------------------------------------------------------- */
.tpl-lestari .les-rsvp { padding: clamp(64px, 9vw, 106px) 0; background: var(--paper-2); }
.tpl-lestari .les-wishes { padding: clamp(64px, 9vw, 106px) 0; }
.tpl-lestari .les-form-grid {
    display: grid;
    grid-template-columns: minmax(0, .85fr) minmax(0, 1.15fr);
    gap: clamp(28px, 6vw, 80px);
    align-items: start;
}
.tpl-lestari .les-form-aside h2 {
    margin: 12px 0 0;
    font-family: var(--display);
    font-size: clamp(1.8rem, 4.2vw, 2.6rem);
    font-weight: 400;
    line-height: 1.12;
}
.tpl-lestari .les-form-aside p {
    max-width: 340px;
    margin: 18px 0 0;
    font-size: .84rem;
    line-height: 1.85;
    color: var(--muted);
}
.tpl-lestari .les-form-card {
    padding: clamp(22px, 4vw, 36px);
    border: 1px solid var(--line);
    border-radius: 22px;
    background: var(--card);
    box-shadow: 0 20px 50px rgba(47, 54, 42, .07);
}
.tpl-lestari .tw-wish-list { max-height: 430px; }

/* ---------------------------------------------------------------------
   Closing
   --------------------------------------------------------------------- */
.tpl-lestari .les-closing {
    position: relative;
    padding: clamp(80px, 12vw, 140px) 22px clamp(60px, 8vw, 90px);
    background: #4c5740;
    color: #f3f0e4;
    text-align: center;
    overflow: hidden;
}
.tpl-lestari .les-closing-leaf {
    position: absolute;
    right: -40px;
    bottom: -30px;
    width: min(360px, 60vw);
    color: rgba(243, 240, 228, .16);
    pointer-events: none;
}
.tpl-lestari .les-closing-leaf svg { width: 100%; height: auto; }
.tpl-lestari .les-closing-inner { position: relative; z-index: 2; max-width: 660px; margin-inline: auto; }
.tpl-lestari .les-monogram-light { color: #f3f0e4; border-color: rgba(243, 240, 228, .5); }
.tpl-lestari .les-monogram-light::after { border-color: rgba(243, 240, 228, .22); }
.tpl-lestari .les-closing-text {
    margin: 26px 0 0;
    font-family: var(--display);
    font-size: clamp(1rem, 2.3vw, 1.15rem);
    font-weight: 300;
    font-style: italic;
    line-height: 1.9;
    color: rgba(243, 240, 228, .9);
}
.tpl-lestari .les-closing h2 {
    margin: 30px 0 0;
    font-family: var(--display);
    font-size: clamp(2.2rem, 6.4vw, 3.4rem);
    font-weight: 400;
    line-height: 1.08;
}
.tpl-lestari .les-closing h2 em { font-style: italic; color: var(--accent-2); font-size: .7em; }
.tpl-lestari .les-closing-date {
    margin: 10px 0 0;
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 600;
    letter-spacing: .28em;
    text-transform: uppercase;
    color: rgba(243, 240, 228, .6);
}
.tpl-lestari .les-closing-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 10px;
    margin-top: 30px;
}
.tpl-lestari .les-btn-light { color: #f3f0e4; border-color: rgba(243, 240, 228, .5); }
.tpl-lestari .les-btn-light:hover { background: #f3f0e4; color: #4c5740; }
.tpl-lestari .les-credit {
    margin: 46px 0 0;
    font-family: var(--body);
    font-size: .54rem;
    letter-spacing: .16em;
    text-transform: uppercase;
    color: rgba(243, 240, 228, .42);
}

/* ---------------------------------------------------------------------
   Animasi khas: daun bergoyang + spora
   --------------------------------------------------------------------- */
.les-spores { position: fixed; inset: 0; z-index: 88; pointer-events: none; overflow: hidden; }
.les-spore {
    position: absolute;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: #b9c6a8;
    box-shadow: 0 0 6px rgba(185, 198, 168, .8);
    opacity: 0;
    animation: les-drift linear infinite;
}
@keyframes les-drift {
    0% { transform: translate3d(0, 12vh, 0); opacity: 0; }
    15% { opacity: .8; }
    60% { transform: translate3d(26px, 46vh, 0) scale(1.15); opacity: .7; }
    100% { transform: translate3d(-18px, -6vh, 0); opacity: 0; }
}
.tpl-lestari .les-cover-leaf { animation: les-sway 9s ease-in-out infinite; transform-origin: bottom center; }
.tpl-lestari .les-leaf-b { animation-delay: -4s; }
@keyframes les-sway {
    0%, 100% { transform: rotate(0deg); }
    50% { transform: rotate(2.5deg); }
}

/* ---------------------------------------------------------------------
   Responsive
   --------------------------------------------------------------------- */
@media (max-width: 900px) {
    .tpl-lestari .les-event-grid { grid-template-columns: 1fr; }
    .tpl-lestari .les-form-grid { grid-template-columns: 1fr; }
    .tpl-lestari .les-form-aside p { max-width: 520px; }
    .tpl-lestari .les-gallery { grid-auto-rows: 150px; }
}

@media (max-width: 620px) {
    .tpl-lestari .les-wrap { width: calc(100% - 34px); }
    .tpl-lestari .les-couple-grid { gap: 16px; }
    .tpl-lestari .les-portrait { border-radius: 140px 140px 14px 14px; }
    .tpl-lestari .les-portrait img { border-radius: 130px 130px 10px 10px; }
    .tpl-lestari .les-parents { font-size: .7rem; }
    .tpl-lestari .les-countdown { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .tpl-lestari .les-count { border-radius: 120px 120px 12px 12px; }
    .tpl-lestari .les-event { grid-template-columns: 96px minmax(0, 1fr); }
    .tpl-lestari .les-gallery { grid-template-columns: repeat(2, 1fr); grid-auto-rows: 140px; }
    .tpl-lestari .les-photo.is-arch { grid-row: span 1; border-radius: 90px 90px 12px 12px; }
    .tpl-lestari .les-photo.is-wide { grid-column: span 1; }
    .tpl-lestari .les-gift-grid { grid-template-columns: 1fr; }
    .tpl-lestari .les-gift { border-radius: 140px 140px 18px 18px; padding-inline: 20px; }
    .tpl-lestari .les-vine { padding-left: 32px; }
    .tpl-lestari .les-vine-dot { left: -35px; }
}

content.text:
Note the `.tpl-lestari .les-cover-leaf { animation: les-sway ...}` and `.les-leaf-b` also has transform rotate(180deg) set earlier. The animation overrides transform, losing 180 rotation. Need fix: animation keyframes rotate from 180 to 182.5. Use separate animation for b:
```css
.tpl-lestari .les-leaf-b{animation-name:les-sway-flip}
@keyframes les-sway-flip{0%,100%{transform:rotate(180deg)}50%{transform:rotate(177.5deg)}}
```
Let me edit later. Also `.les-cover-leaf` animation defined after transform-origin; the earlier `.les-leaf-b { transform: rotate(180deg) }` will be overridden by animation even with no delay. Fix now.

And lestari.js: spores + grow reveal + slight parallax on cover arch. Let's write.

