.tpl-lestari .les-leaf-b { animation-name: les-sway-flip; animation-delay: -4s; }
@keyframes les-sway {
    0%, 100% { transform: rotate(0deg); }
    50% { transform: rotate(2.5deg); }
}
@keyframes les-sway-flip {
    0%, 100% { transform: rotate(180deg); }
    50% { transform: rotate(177.5deg); }
}

