/* LESTARI — spora taman yang melayang dan parallax lengkung cover. */
(function () {
    'use strict';

    if (!document.body.classList.contains('tpl-lestari')) return;

    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    function startSpores() {
        if (reduceMotion || document.querySelector('.les-spores')) return;

        var layer = document.createElement('div');
        layer.className = 'les-spores';
        layer.setAttribute('aria-hidden', 'true');

        for (var i = 0; i < 12; i += 1) {
            var spore = document.createElement('span');
            spore.className = 'les-spore';
            spore.style.left = (Math.random() * 100).toFixed(2) + '%';
            spore.style.bottom = (-10 + Math.random() * 40).toFixed(0) + '%';
            spore.style.animationDuration = (16 + Math.random() * 16).toFixed(1) + 's';
            spore.style.animationDelay = (-Math.random() * 24).toFixed(1) + 's';
            spore.style.opacity = (0.3 + Math.random() * 0.5).toFixed(2);
            layer.appendChild(spore);
        }

        document.body.appendChild(layer);
    }

    window.setTimeout(startSpores, 1300);

    var arch = document.querySelector('.les-cover-arch img');

    if (arch && !reduceMotion && window.matchMedia('(pointer: fine)').matches) {
        var ticking = false;

        document.addEventListener('mousemove', function (event) {
            if (ticking) return;
            ticking = true;
            window.requestAnimationFrame(function () {
                var x = (event.clientX / window.innerWidth - 0.5) * 10;
                var y = (event.clientY / window.innerHeight - 0.5) * 10;
                arch.style.transform = 'scale(1.03) translate3d(' + x.toFixed(2) + 'px,' + y.toFixed(2) + 'px,0)';
                ticking = false;
            });
        }, { passive: true });
    }
})();

/* =====================================================================
   MAHARAJA — Luxury Royal Wedding
   Hitam pekat, emas, geometri istana, tipografi Cinzel.
   ===================================================================== */

.tpl-maharaja {
    --bg: #0a0908;
    --paper: #0a0908;
    --paper-2: #120e08;
    --card: #14100a;
    --ink: #f4ead1;
    --ink-soft: #d8c9a6;
    --muted: #9a8a68;
    --accent: #c9a54b;
    --accent-2: #e6cd8b;
    --accent-soft: rgba(201, 165, 75, .12);
    --line: rgba(201, 165, 75, .28);
    --field-bg: rgba(255, 255, 255, .035);
    --field-radius: 0px;
    --btn-ink: #100c06;
    --btn-radius: 0px;
    --dock-bg: rgba(18, 14, 8, .95);
    --dock-ink: #e6cd8b;
    --display: 'Cinzel', 'Trajan Pro', Georgia, serif;
    --body: 'Cormorant Garamond', Georgia, serif;
    background: var(--bg);
    color: var(--ink);
    font-size: 17px;
}

.tpl-maharaja .tpl-main { overflow: hidden; background: var(--bg); }

.tpl-maharaja .mhr-wrap {
    width: min(1080px, calc(100% - 44px));
    margin-inline: auto;
}

.tpl-maharaja .mhr-kicker {
    display: inline-block;
    font-family: var(--display);
    font-size: .56rem;
    font-weight: 500;
    letter-spacing: .4em;
    text-transform: uppercase;
    color: var(--accent);
}

.tpl-maharaja .mhr-title {
    margin: 14px 0 0;
    font-family: var(--display);
    font-size: clamp(1.45rem, 3.6vw, 2.3rem);
    font-weight: 500;
    letter-spacing: .18em;
    line-height: 1.3;
    text-transform: uppercase;
    background: linear-gradient(100deg, #9c7c35 0%, #e9d49a 28%, #c9a54b 52%, #f4e6ba 74%, #9c7c35 100%);
    background-size: 220% auto;
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    animation: mhr-shimmer 9s linear infinite;
}

@keyframes mhr-shimmer {
    to { background-position: 220% center; }
}

.tpl-maharaja .mhr-head {
    margin-bottom: clamp(34px, 5vw, 54px);
    text-align: center;
}

.tpl-maharaja .mhr-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 12px 22px;
    border: 1px solid var(--accent);
    border-radius: 0;
    background: transparent;
    color: var(--accent-2);
    font-family: var(--display);
    font-size: .54rem;
    font-weight: 500;
    letter-spacing: .22em;
    text-transform: uppercase;
    text-decoration: none;
    transition: background .25s ease, color .25s ease;
}
.tpl-maharaja .mhr-btn:hover { background: var(--accent); color: var(--btn-ink); }
.tpl-maharaja .mhr-btn .tpl-icon { width: 14px; height: 14px; }

/* ---------------------------------------------------------------------
   Cover
   --------------------------------------------------------------------- */
.tpl-maharaja .mhr-cover {
    background:
        radial-gradient(700px 500px at 50% 18%, rgba(201, 165, 75, .17), transparent 68%),
        radial-gradient(500px 400px at 50% 100%, rgba(201, 165, 75, .08), transparent 70%),
        #080705;
    color: var(--ink);
}

.tpl-maharaja .mhr-cover-texture {
    position: absolute;
    inset: 0;
    z-index: 0;
    opacity: .5;
    background-image:
