.tpl-maharaja .mhr-event-venue { margin: 0; font-size: 1.05rem; font-weight: 500; color: var(--ink); }
.tpl-maharaja .mhr-event-address { margin: 5px 0 18px; font-size: .82rem; line-height: 1.7; color: var(--muted); }
