.tpl-maharaja .tw-choice:hover { border-color: var(--accent-2); }
.tpl-maharaja .tw-btn { font-family: var(--display); letter-spacing: .26em; background: linear-gradient(110deg, #a9873b, #e6cd8b 45%, #b8944a 75%, #e6cd8b); background-size: 180% auto; color: #120c04; }
.tpl-maharaja .tw-btn:hover { background-position: right center; filter: none; }
.tpl-maharaja .tw-wish { background: rgba(201, 165, 75, .04); }
.tpl-maharaja .tw-wish-head strong { color: var(--accent-2); }
.tpl-maharaja .tw-wish-list { max-height: 420px; }

/* ---------------------------------------------------------------------
   Closing
   --------------------------------------------------------------------- */
.tpl-maharaja .mhr-closing {
    padding: clamp(80px, 12vw, 150px) 22px clamp(60px, 8vw, 90px);
    background:
        radial-gradient(600px 380px at 50% 0, rgba(201, 165, 75, .12), transparent 70%),
        #050403;
    border-top: 1px solid var(--line);
    text-align: center;
}
.tpl-maharaja .mhr-closing-crest { width: 96px; margin: 0 auto 24px; color: var(--accent); }
.tpl-maharaja .mhr-closing-crest svg { width: 100%; height: auto; }
.tpl-maharaja .mhr-closing-text {
    max-width: 660px;
    margin: 0 auto;
    font-family: var(--body);
    font-size: clamp(1rem, 2.3vw, 1.14rem);
    font-weight: 300;
    font-style: italic;
    line-height: 1.9;
    color: var(--ink-soft);
}
.tpl-maharaja .mhr-closing-names {
    margin: 34px 0 0;
    font-family: var(--display);
    font-size: clamp(1.3rem, 4.4vw, 2.2rem);
    font-weight: 500;
    letter-spacing: .16em;
    text-transform: uppercase;
    background: linear-gradient(100deg, #a9873b, #f2e2b4 35%, #c9a54b 60%, #f7ecc9 82%, #a9873b);
    background-size: 220% auto;
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    animation: mhr-shimmer 8s linear infinite;
}
.tpl-maharaja .mhr-closing-names em { font-family: var(--body); font-style: italic; font-size: .6em; }
.tpl-maharaja .mhr-closing-date {
    margin: 12px 0 0;
    font-family: var(--display);
    font-size: .5rem;
    letter-spacing: .3em;
    text-transform: uppercase;
    color: var(--muted);
}
.tpl-maharaja .mhr-closing-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 10px;
    margin-top: 30px;
}
.tpl-maharaja .mhr-credit {
    margin: 46px 0 0;
    font-family: var(--display);
    font-size: .44rem;
    letter-spacing: .32em;
    text-transform: uppercase;
    color: var(--muted);
}

/* ---------------------------------------------------------------------
   Efek khas: kilau emas mengikuti kursor
   --------------------------------------------------------------------- */
.mhr-glow {
    position: fixed;
    z-index: 2;
    width: 360px;
    height: 360px;
    border-radius: 50%;
    pointer-events: none;
    background: radial-gradient(circle, rgba(230, 205, 139, .10), transparent 62%);
    transform: translate(-50%, -50%);
    transition: opacity .5s ease;
    opacity: 0;
}

/* ---------------------------------------------------------------------
   Responsive
   --------------------------------------------------------------------- */
@media (max-width: 860px) {
    .tpl-maharaja .mhr-couple-grid { grid-template-columns: 1fr; gap: 26px; }
    .tpl-maharaja .mhr-amp { padding-bottom: 0; }
    .tpl-maharaja .mhr-couple-grid .mhr-person { max-width: 420px; margin-inline: auto; }
    .tpl-maharaja .mhr-event-grid { grid-template-columns: 1fr; }
    .tpl-maharaja .mhr-chronicle::before { left: 6px; }
    .tpl-maharaja .mhr-chronicle-item { grid-template-columns: 20px 1fr; gap: 14px; }
    .tpl-maharaja .mhr-chronicle-year { grid-column: 2; text-align: left; }
    .tpl-maharaja .mhr-chronicle-dot { grid-column: 1; grid-row: 1 / 3; margin-top: 5px; }
    .tpl-maharaja .mhr-chronicle-item > div { grid-column: 2; }
}

@media (max-width: 620px) {
    .tpl-maharaja .mhr-wrap { width: calc(100% - 34px); }
    .tpl-maharaja .mhr-countdown { grid-template-columns: repeat(2, 1fr); }
    .tpl-maharaja .mhr-gift-grid { grid-template-columns: 1fr; }
    .tpl-maharaja .mhr-gallery { grid-template-columns: repeat(2, 1fr); }
    .tpl-maharaja .mhr-photo:nth-child(4n + 1) img { aspect-ratio: 1; }
    .tpl-maharaja .mhr-cover-frame { inset: 9px; }
    .tpl-maharaja .mhr-corner { width: 34px; height: 34px; }
    .tpl-maharaja .mhr-corner-tl { top: 14px; left: 14px; }
    .tpl-maharaja .mhr-corner-tr { top: 14px; right: 14px; }
    .tpl-maharaja .mhr-corner-bl { bottom: 14px; left: 14px; }
    .tpl-maharaja .mhr-corner-br { bottom: 14px; right: 14px; }
}

