/* Serpihan kertas */
.arm-flecks {
    position: fixed;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    overflow: hidden;
}
.arm-flecks span {
    position: absolute;
    border-radius: 1px;
    background: rgba(180, 87, 59, .35);
    animation: arm-fleck-drift linear infinite;
}
@keyframes arm-fleck-drift {
    0% { transform: translate3d(0, 0, 0) rotate(0deg); }
    50% { transform: translate3d(18px, -22px, 0) rotate(90deg); }
    100% { transform: translate3d(-12px, -46px, 0) rotate(180deg); }
}

