/* Butir emas dan gerak gunungan */
.tpl-puspita .pus-gunungan {
    animation: pus-gunungan-float 9s ease-in-out infinite;
}
@keyframes pus-gunungan-float {
    0%, 100% { transform: translate(-50%, 0); }
    50% { transform: translate(-50%, -10px); }
}

.pus-sparkles {
    position: fixed;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    overflow: hidden;
}
.pus-sparkles span {
    position: absolute;
    bottom: -12px;
    border-radius: 0;
    background: rgba(212, 175, 85, .8);
    transform: rotate(45deg);
    animation: pus-spark-rise linear infinite;
}
@keyframes pus-spark-rise {
    0% { transform: translateY(0) rotate(45deg); opacity: 0; }
    12% { opacity: 1; }
    100% { transform: translateY(-110vh) rotate(225deg); opacity: 0; }
}

