input.content:
/* =====================================================================
   ASMARA — Romantic Blush Wedding
   Mawar pudar, kabut lembut, hati, dan tipografi kaligrafi.
   ===================================================================== */

.tpl-asmara {
    --bg: #fbf1ee;
    --paper: #fbf1ee;
    --paper-2: #f6e3df;
    --card: #fffaf8;
    --ink: #4a3336;
    --ink-soft: #6b4d51;
    --muted: #9a7d80;
    --accent: #b8727b;
    --accent-2: #d9a3a8;
    --accent-soft: rgba(184, 114, 123, .12);
    --line: rgba(184, 114, 123, .26);
    --field-bg: rgba(255, 255, 255, .62);
    --field-radius: 12px;
    --btn-ink: #fffaf8;
    --btn-radius: 999px;
    --dock-bg: rgba(74, 51, 54, .92);
    --dock-ink: #fbe9e5;
    --display: 'Cormorant Garamond', Georgia, serif;
    --body: 'Mulish', 'Segoe UI', sans-serif;
    --script: 'Parisienne', cursive;
    background:
        radial-gradient(600px 420px at 12% 8%, rgba(217, 163, 168, .2), transparent 62%),
        radial-gradient(540px 420px at 88% 34%, rgba(184, 114, 123, .12), transparent 64%),
        var(--bg);
    color: var(--ink);
    font-size: 16.5px;
}

.tpl-asmara .asm-main { overflow: hidden; }

.tpl-asmara .asm-wrap {
    width: min(1060px, calc(100% - 40px));
    margin-inline: auto;
}
.tpl-asmara .asm-narrow { width: min(700px, calc(100% - 40px)); }

.tpl-asmara .asm-script {
    margin: 0;
    font-family: var(--script);
    font-size: clamp(1.6rem, 4.2vw, 2.3rem);
    line-height: 1.25;
    color: var(--accent);
}

.tpl-asmara .asm-kicker {
    display: inline-block;
    font-family: var(--body);
    font-size: .56rem;
    font-weight: 600;
    letter-spacing: .34em;
    text-transform: uppercase;
    color: var(--accent);
}

.tpl-asmara .asm-title {
    margin: 8px 0 0;
    font-family: var(--display);
    font-size: clamp(1.9rem, 5.4vw, 3rem);
    font-weight: 400;
    line-height: 1.05;
    letter-spacing: .01em;
}

.tpl-asmara .asm-sub { margin-top: 8px; font-size: clamp(1.35rem, 3.6vw, 1.8rem); }

.tpl-asmara .asm-head { margin-bottom: clamp(32px, 5vw, 52px); text-align: center; }

.tpl-asmara .asm-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 12px 24px;
    border: 1px solid var(--accent);
    border-radius: 999px;
    background: transparent;
    color: var(--accent);
    font-family: var(--body);
    font-size: .6rem;
    font-weight: 700;
    letter-spacing: .18em;
    text-transform: uppercase;
    text-decoration: none;
    transition: background .25s ease, color .25s ease, transform .25s ease;
}
.tpl-asmara .asm-btn:hover { background: var(--accent); color: var(--btn-ink); transform: translateY(-1px); }
.tpl-asmara .asm-btn .tpl-icon { width: 14px; height: 14px; }

/* ---------------------------------------------------------------------
   Cover
   --------------------------------------------------------------------- */
.tpl-asmara .asm-cover { background: #3a262a; }

.tpl-asmara .asm-cover-media img {
    transform: scale(1.04);
    filter: saturate(.86) contrast(1.02);
}

.tpl-asmara .asm-cover-veil {
    position: absolute;
    inset: 0;
    z-index: 1;
    background:
        linear-gradient(180deg, rgba(58, 38, 42, .34), rgba(58, 38, 42, .12) 36%, rgba(58, 38, 42, .58) 100%),
        radial-gradient(circle at 50% 44%, rgba(217, 163, 168, .18), transparent 62%);
}

.tpl-asmara .asm-cover-glow {
    position: absolute;
    z-index: 2;
    width: min(540px, 90vw);
    height: min(540px, 90vw);
    border-radius: 50%;
    background: radial-gradient(circle, rgba(251, 233, 229, .22), transparent 62%);
    pointer-events: none;
}

.tpl-asmara .asm-cover-inner {
    position: relative;
    z-index: 3;
    width: min(540px, 100%);
    color: #fff6f3;
    text-align: center;
}

.tpl-asmara .asm-seal {
    display: grid;
    place-items: center;
    width: 74px;
    height: 74px;
    margin: 0 auto 18px;
    border: 1px solid rgba(255, 246, 243, .6);
    border-radius: 50%;
    background: rgba(255, 246, 243, .1);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
}
.tpl-asmara .asm-seal span {
    font-family: var(--display);
    font-size: 1.3rem;
    letter-spacing: .06em;
    color: #fff6f3;
}

.tpl-asmara .asm-cover-script {
    font-size: clamp(1.7rem, 4.6vw, 2.4rem);
    color: #f9dfda;
}

.tpl-asmara .asm-cover-names {
    margin: 6px 0 0;
    font-family: var(--display);
    font-size: clamp(2.2rem, 8.2vw, 3.9rem);
    font-weight: 400;
    line-height: 1.15;
    letter-spacing: .02em;
    color: #fffaf8;
    text-shadow: 0 2px 30px rgba(58, 38, 42, .35);
}
.tpl-asmara .asm-cover-names span { display: block; }
.tpl-asmara .asm-cover-names em {
    display: block;
    margin: .02em 0;
    font-family: var(--script);
    font-size: .55em;
    color: #f6cdc8;
    line-height: 1;
}

.tpl-asmara .asm-cover-date {
    margin: 14px 0 0;
    font-family: var(--body);
    font-size: .64rem;
    font-weight: 500;
    letter-spacing: .34em;
    color: rgba(255, 246, 243, .82);
}

.tpl-asmara .asm-guest { margin-top: 24px; color: rgba(255, 246, 243, .82); }
.tpl-asmara .asm-guest span { font-family: var(--body); font-size: .52rem; letter-spacing: .24em; color: rgba(255, 246, 243, .62); }
.tpl-asmara .asm-guest strong { font-family: var(--display); font-size: 1.3rem; color: #fffaf8; }

.tpl-asmara .asm-open {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    margin-top: 22px;
    padding: 13px 30px;
    border: 1px solid rgba(255, 246, 243, .66);
    border-radius: 999px;
    background: rgba(255, 246, 243, .16);
    color: #fffaf8;
    font-family: var(--body);
    font-size: .58rem;
    font-weight: 700;
    letter-spacing: .24em;
    text-transform: uppercase;
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    transition: background .25s ease, color .25s ease;
}
.tpl-asmara .asm-open:hover { background: #fff6f3; color: #4a3336; }
.tpl-asmara .asm-open .tpl-icon { width: 14px; height: 14px; fill: currentColor; }

.tpl-asmara .asm-cover-foot {
    position: absolute;
    bottom: max(16px, env(safe-area-inset-bottom));
    left: 50%;
    z-index: 3;
    transform: translateX(-50%);
    margin: 0;
    font-family: var(--script);
    font-size: 1.2rem;
    color: rgba(255, 246, 243, .78);
    white-space: nowrap;
}

/* ---------------------------------------------------------------------
   Hero
   --------------------------------------------------------------------- */
.tpl-asmara .asm-hero {
    position: relative;
    padding: clamp(70px, 11vw, 128px) 0 clamp(54px, 8vw, 88px);
    overflow: hidden;
    background:
        radial-gradient(560px 400px at 50% 0, rgba(217, 163, 168, .22), transparent 68%),
        linear-gradient(180deg, var(--paper-2), var(--paper));
    text-align: center;
}
.tpl-asmara .asm-hero-glow {
    position: absolute;
    top: -120px;
    left: 50%;
    width: min(720px, 120vw);
    height: 460px;
    transform: translateX(-50%);
    border-radius: 50%;
    background: radial-gradient(circle, rgba(255, 255, 255, .6), transparent 66%);
    pointer-events: none;
}
.tpl-asmara .asm-hero-inner { position: relative; z-index: 2; }

.tpl-asmara .asm-arabic {
    margin: 0 0 14px;
    font-family: 'Traditional Arabic', 'Scheherazade New', serif;
    font-size: 1.6rem;
    color: var(--ink-soft);
}

.tpl-asmara .asm-hero-names {
    margin: 14px 0 0;
    font-family: var(--display);
    font-size: clamp(2rem, 6.4vw, 3.4rem);
    font-weight: 400;
    line-height: 1.2;
}
.tpl-asmara .asm-hero-names span { display: block; }
.tpl-asmara .asm-hero-names em {
    display: block;
    font-family: var(--script);
    font-size: .5em;
    color: var(--accent);
    line-height: 1;
}

.tpl-asmara .asm-hero-script { margin-top: 6px; }

.tpl-asmara .asm-hero-text {
    max-width: 600px;
    margin: 20px auto 0;
    font-size: .9rem;
    line-height: 1.9;
    color: var(--ink-soft);
}

.tpl-asmara .asm-hero-date {
    margin: 18px 0 0;
    font-family: var(--body);
    font-size: .6rem;
    font-weight: 600;
    letter-spacing: .34em;
    text-transform: uppercase;
    color: var(--accent);
}

.tpl-asmara .asm-scroll {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    margin-top: 26px;
    font-family: var(--body);
    font-size: .56rem;
    letter-spacing: .26em;
    text-transform: uppercase;
    color: var(--accent);
    text-decoration: none;
}
.tpl-asmara .asm-scroll .tpl-icon { width: 15px; height: 15px; animation: asm-bob 2.8s ease-in-out infinite; }
@keyframes asm-bob {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(6px); }
}

/* ---------------------------------------------------------------------
   Sections
   --------------------------------------------------------------------- */
.tpl-asmara .asm-section { position: relative; padding: clamp(60px, 9vw, 108px) 0; }

/* ---------------------------------------------------------------------
   Couple
   --------------------------------------------------------------------- */
.tpl-asmara .asm-couple {
    background:
        radial-gradient(480px 320px at 100% 0, rgba(217, 163, 168, .14), transparent 66%),
        var(--paper);
}
.tpl-asmara .asm-couple-grid {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    gap: clamp(14px, 3vw, 40px);
    align-items: center;
    max-width: 880px;
    margin-inline: auto;
}
.tpl-asmara .asm-person { text-align: center; }

.tpl-asmara .asm-portrait {
    width: min(280px, 88%);
    margin-inline: auto;
    padding: 8px;
    border: 1px solid var(--line);
    border-radius: 50%;
    background: linear-gradient(150deg, #fffaf8, #f6dfda);
    box-shadow: 0 22px 54px rgba(122, 76, 82, .2), inset 0 0 0 6px rgba(255, 255, 255, .7);
}
.tpl-asmara .asm-portrait img {
    width: 100%;
    aspect-ratio: 1;
    object-fit: cover;
    border-radius: 50%;
    filter: saturate(.9) contrast(1.02);
}

.tpl-asmara .asm-role {
    margin: 18px 0 0;
    font-family: var(--body);
    font-size: .54rem;
    font-weight: 600;
    letter-spacing: .3em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-asmara .asm-person h3 {
    margin: 6px 0 0;
    font-family: var(--display);
    font-size: clamp(1.4rem, 3.4vw, 1.8rem);
    font-weight: 500;
}
.tpl-asmara .asm-parents {
    max-width: 260px;
    margin: 6px auto 0;
    font-size: .76rem;
    line-height: 1.7;
    color: var(--muted);
}
.tpl-asmara .asm-social {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    margin-top: 8px;
    font-size: .68rem;
    color: var(--accent);
    text-decoration: none;
}
.tpl-asmara .asm-social .tpl-icon { width: 12px; height: 12px; }

.tpl-asmara .asm-connector {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    color: var(--accent);
}
.tpl-asmara .asm-connector .tpl-icon { width: 24px; height: 24px; fill: rgba(184, 114, 123, .16); }
.tpl-asmara .asm-connector-line { display: block; width: 1px; height: 42px; background: linear-gradient(180deg, transparent, var(--line)); }
.tpl-asmara .asm-connector-line:last-child { background: linear-gradient(0deg, transparent, var(--line)); }

/* ---------------------------------------------------------------------
   Quote
   --------------------------------------------------------------------- */
.tpl-asmara .asm-quote-section {
    position: relative;
    padding: clamp(52px, 8vw, 88px) 0;
    background:
        radial-gradient(460px 300px at 50% 50%, rgba(217, 163, 168, .2), transparent 70%),
        var(--paper-2);
}
.tpl-asmara .asm-quote-card {
    position: relative;
    max-width: 780px;
    margin-inline: auto;
    padding: clamp(36px, 6vw, 58px) clamp(24px, 5vw, 60px);
    border-radius: 26px;
    background: rgba(255, 250, 248, .82);
    box-shadow: 0 22px 60px rgba(122, 76, 82, .13);
    text-align: center;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}
.tpl-asmara .asm-quote-heart {
    display: grid;
    place-items: center;
    width: 44px;
    height: 44px;
    margin: -60px auto 18px;
    border-radius: 50%;
    background: var(--paper-2);
    color: var(--accent);
    box-shadow: 0 0 0 8px rgba(255, 250, 248, .8);
}
.tpl-asmara .asm-quote-heart .tpl-icon { width: 20px; height: 20px; fill: rgba(184, 114, 123, .2); }
.tpl-asmara .asm-quote-card blockquote {
    margin: 0;
    font-family: var(--display);
    font-size: clamp(1.15rem, 2.8vw, 1.5rem);
    font-style: italic;
    line-height: 1.8;
    color: var(--ink-soft);
}
.tpl-asmara .asm-quote-card cite {
    display: block;
    margin-top: 16px;
    font-family: var(--body);
    font-size: .56rem;
    font-style: normal;
    font-weight: 600;
    letter-spacing: .28em;
    text-transform: uppercase;
    color: var(--accent);
}

/* ---------------------------------------------------------------------
   Countdown
   --------------------------------------------------------------------- */
.tpl-asmara .asm-countdown-section { background: var(--paper); }
.tpl-asmara .asm-countdown {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: clamp(8px, 2vw, 16px);
    max-width: 720px;
    margin-inline: auto;
}
.tpl-asmara .asm-count {
    padding: clamp(16px, 3vw, 26px) 4px;
    border: 1px solid rgba(255, 255, 255, .7);
    border-radius: 18px;
    background: linear-gradient(160deg, rgba(255, 255, 255, .78), rgba(246, 227, 223, .62));
    box-shadow: 0 14px 34px rgba(122, 76, 82, .1);
    text-align: center;
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
}
.tpl-asmara .asm-count strong {
    display: block;
    font-family: var(--display);
    font-size: clamp(1.6rem, 4.4vw, 2.4rem);
    font-weight: 500;
    line-height: 1;
    color: var(--accent);
    font-variant-numeric: tabular-nums;
}
.tpl-asmara .asm-count span {
    display: block;
    margin-top: 8px;
    font-family: var(--body);
    font-size: .5rem;
    font-weight: 600;
    letter-spacing: .24em;
    text-transform: uppercase;
    color: var(--muted);
}

/* ---------------------------------------------------------------------
   Events
   --------------------------------------------------------------------- */
.tpl-asmara .asm-events {
    background:
        radial-gradient(500px 340px at 0 100%, rgba(217, 163, 168, .16), transparent 66%),
        var(--paper-2);
}
.tpl-asmara .asm-event-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: clamp(16px, 3vw, 26px);
    max-width: 880px;
    margin-inline: auto;
}
.tpl-asmara .asm-event {
    position: relative;
    padding: clamp(30px, 4.5vw, 44px) clamp(20px, 3.4vw, 34px);
    border: 1px solid rgba(255, 255, 255, .8);
    border-radius: 22px;
    background: rgba(255, 250, 248, .78);
    box-shadow: 0 18px 44px rgba(122, 76, 82, .1);
    text-align: center;
}
.tpl-asmara .asm-event-badge {
    display: grid;
    place-items: center;
    width: 52px;
    height: 52px;
    margin: 0 auto 14px;
    border-radius: 50%;
    background: var(--accent-soft);
    color: var(--accent);
}
.tpl-asmara .asm-event-badge .tpl-icon { width: 20px; height: 20px; }
.tpl-asmara .asm-event h3 {
    margin: 0;
    font-family: var(--display);
    font-size: clamp(1.25rem, 2.8vw, 1.5rem);
    font-weight: 600;
}
.tpl-asmara .asm-event-date { margin: 8px 0 0; font-size: .82rem; color: var(--ink-soft); }
.tpl-asmara .asm-event-time {
    margin: 2px 0 0;
    font-size: .56rem;
    font-weight: 700;
    letter-spacing: .2em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-asmara .asm-event-divider {
    display: block;
    width: 46px;
    height: 1px;
    margin: 16px auto;
    background: var(--accent-2);
}
.tpl-asmara .asm-event-venue { margin: 0; font-family: var(--display); font-size: 1.06rem; font-weight: 600; }
.tpl-asmara .asm-event-address { margin: 4px 0 18px; font-size: .76rem; line-height: 1.7; color: var(--muted); }
.tpl-asmara .asm-live { margin-top: 32px; text-align: center; }
.tpl-asmara .asm-live p { margin-bottom: 10px; }

/* ---------------------------------------------------------------------
   Story
   --------------------------------------------------------------------- */
.tpl-asmara .asm-story { background: var(--paper); }
.tpl-asmara .asm-heart-line {
    position: relative;
    max-width: 720px;
    margin-inline: auto;
}
.tpl-asmara .asm-heart-line::before {
    content: '';
    position: absolute;
    top: 10px;
    bottom: 10px;
    left: 50%;
    width: 1px;
    background: linear-gradient(180deg, transparent, var(--line) 8%, var(--line) 92%, transparent);
}
.tpl-asmara .asm-story-item {
    position: relative;
    display: grid;
    grid-template-columns: 1fr 52px 1fr;
    gap: 18px;
    padding-bottom: 28px;
}
.tpl-asmara .asm-story-item:last-child { padding-bottom: 0; }
.tpl-asmara .asm-story-dot {
    grid-column: 2;
    display: grid;
    place-items: center;
    align-self: start;
    width: 38px;
    height: 38px;
    margin: 0 auto;
    border-radius: 50%;
    background: var(--paper);
    color: var(--accent);
    box-shadow: 0 0 0 6px var(--paper);
}
.tpl-asmara .asm-story-dot .tpl-icon { width: 16px; height: 16px; fill: rgba(184, 114, 123, .22); }
.tpl-asmara .asm-story-card {
    grid-column: 3;
    padding: 20px 22px;
    border-radius: 18px;
    background: rgba(255, 250, 248, .86);
    box-shadow: 0 12px 30px rgba(122, 76, 82, .09);
}
.tpl-asmara .asm-story-item:nth-child(even) .asm-story-card { grid-column: 1; grid-row: 1; text-align: right; }
.tpl-asmara .asm-story-date {
    margin: 0;
    font-family: var(--body);
    font-size: .54rem;
    font-weight: 700;
    letter-spacing: .26em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-asmara .asm-story-card h3 {
    margin: 6px 0 0;
    font-family: var(--display);
    font-size: 1.22rem;
    font-weight: 600;
}
.tpl-asmara .asm-story-card p { margin: 6px 0 0; font-size: .8rem; line-height: 1.8; color: var(--ink-soft); }

/* ---------------------------------------------------------------------
   Gallery
   --------------------------------------------------------------------- */
.tpl-asmara .asm-gallery-section { background: var(--paper-2); }
.tpl-asmara .asm-gallery {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-auto-rows: 220px;
    gap: 12px;
}
.tpl-asmara .asm-photo {
    position: relative;
    padding: 0;
    border: 5px solid #fffaf8;
    border-radius: 22px;
    background: #f6e3df;
    box-shadow: 0 16px 38px rgba(122, 76, 82, .14);
    cursor: zoom-in;
    overflow: hidden;
}
.tpl-asmara .asm-photo.is-wide { grid-column: span 2; }
.tpl-asmara .asm-photo img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: saturate(.92);
    transition: transform .9s cubic-bezier(.2, .7, .2, 1), filter .4s ease;
}
.tpl-asmara .asm-photo:hover img { transform: scale(1.05); filter: saturate(1); }
.tpl-asmara .asm-hashtag {
    margin: 26px 0 0;
    font-family: var(--script);
    font-size: clamp(1.3rem, 3.4vw, 1.7rem);
    text-align: center;
    color: var(--accent);
}

/* ---------------------------------------------------------------------
   Gifts
   --------------------------------------------------------------------- */
.tpl-asmara .asm-gifts { background: var(--paper); }
.tpl-asmara .asm-gift-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18px;
    max-width: 760px;
    margin-inline: auto;
}
.tpl-asmara .asm-gift {
    padding: 32px 24px 26px;
    border: 1px solid rgba(255, 255, 255, .8);
    border-radius: 22px;
    background: rgba(255, 250, 248, .8);
    box-shadow: 0 18px 44px rgba(122, 76, 82, .1);
    text-align: center;
}
.tpl-asmara .asm-gift-icon {
    display: grid;
    place-items: center;
    width: 48px;
    height: 48px;
    margin: 0 auto 12px;
    border-radius: 50%;
    background: var(--accent-soft);
    color: var(--accent);
}
.tpl-asmara .asm-gift-icon .tpl-icon { width: 19px; height: 19px; }
.tpl-asmara .asm-gift-bank {
    display: block;
    font-family: var(--body);
    font-size: .56rem;
    font-weight: 700;
    letter-spacing: .26em;
    text-transform: uppercase;
    color: var(--accent);
}
.tpl-asmara .asm-gift-number {
    margin: 10px 0 0;
    font-family: var(--display);
    font-size: clamp(1.2rem, 3.2vw, 1.5rem);
    font-weight: 600;
    letter-spacing: .05em;
    word-break: break-all;
}
.tpl-asmara .asm-gift-name { margin: 2px 0 16px; font-size: .72rem; color: var(--muted); }

/* ---------------------------------------------------------------------
   RSVP / wishes
   --------------------------------------------------------------------- */
.tpl-asmara .asm-rsvp {
    background:
        radial-gradient(460px 300px at 100% 0, rgba(217, 163, 168, .18), transparent 68%),
        var(--paper-2);
}
.tpl-asmara .asm-wishes { background: var(--paper); }
.tpl-asmara .asm-form-card {
    padding: clamp(24px, 4.5vw, 40px);
    border: 1px solid rgba(255, 255, 255, .8);
    border-radius: 24px;
    background: rgba(255, 250, 248, .82);
    box-shadow: 0 20px 50px rgba(122, 76, 82, .12);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}
.tpl-asmara .tw-label { font-family: var(--body); font-size: .55rem; font-weight: 700; letter-spacing: .22em; }
.tpl-asmara .tw-btn { background: linear-gradient(120deg, #b8727b, #cf9298); color: #fffaf8; letter-spacing: .22em; }
.tpl-asmara .tw-btn:hover { filter: brightness(1.04); }
.tpl-asmara .tw-wish { background: rgba(255, 255, 255, .6); }
.tpl-asmara .tw-wish-head strong { color: var(--accent); }
.tpl-asmara .tw-alert-ok { --ok-bg: #eef7ef; --ok-ink: #27563a; --ok-line: #c3dcc7; }
.tpl-asmara .tw-alert-error { --err-bg: #fbeeee; --err-ink: #7a2222; --err-line: #e6b6b6; }

/* ---------------------------------------------------------------------
   Closing
   --------------------------------------------------------------------- */
.tpl-asmara .asm-closing {
    position: relative;
    padding: clamp(76px, 11vw, 140px) 0 clamp(56px, 8vw, 88px);
    overflow: hidden;
    background:
        radial-gradient(600px 420px at 50% 10%, rgba(246, 205, 200, .26), transparent 68%),
        linear-gradient(165deg, #6b4449, #4a3336 70%, #3d2a2d);
    color: #fff6f3;
    text-align: center;
}
.tpl-asmara .asm-closing-hearts {
    position: absolute;
    inset: 0;
    pointer-events: none;
    background-image: radial-gradient(circle at 20% 30%, rgba(246, 205, 200, .5) 0 2px, transparent 3px),
        radial-gradient(circle at 76% 22%, rgba(246, 205, 200, .4) 0 2px, transparent 3px),
        radial-gradient(circle at 40% 78%, rgba(246, 205, 200, .35) 0 2px, transparent 3px),
        radial-gradient(circle at 86% 68%, rgba(246, 205, 200, .45) 0 2px, transparent 3px);
    background-size: 220px 220px;
    opacity: .6;
}
.tpl-asmara .asm-closing-inner { position: relative; z-index: 2; }
.tpl-asmara .asm-closing-icon {
    display: grid;
    place-items: center;
    width: 54px;
    height: 54px;
    margin: 0 auto 18px;
    border: 1px solid rgba(255, 246, 243, .4);
    border-radius: 50%;
    color: #f6cdc8;
}
.tpl-asmara .asm-closing-icon .tpl-icon { width: 22px; height: 22px; fill: rgba(246, 205, 200, .3); }
.tpl-asmara .asm-closing-script { font-size: clamp(1.7rem, 4.6vw, 2.4rem); color: #f6cdc8; }
.tpl-asmara .asm-closing-text {
    max-width: 660px;
    margin: 18px auto 0;
    font-family: var(--display);
    font-size: clamp(1rem, 2.2vw, 1.16rem);
    font-style: italic;
    line-height: 1.9;
    color: rgba(255, 246, 243, .82);
}
.tpl-asmara .asm-closing-names {
    margin: 28px 0 0;
    font-family: var(--display);
    font-size: clamp(1.5rem, 4.8vw, 2.3rem);
    font-weight: 400;
    color: #fffaf8;
}
.tpl-asmara .asm-closing-names em { font-family: var(--script); font-size: .7em; color: #f6cdc8; }
.tpl-asmara .asm-closing-date {
    margin: 8px 0 0;
    font-family: var(--body);
    font-size: .56rem;
    font-weight: 600;
    letter-spacing: .3em;
    text-transform: uppercase;
    color: rgba(255, 246, 243, .6);
}
.tpl-asmara .asm-closing-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 10px;
    margin-top: 28px;
}
.tpl-asmara .asm-closing .asm-btn { border-color: rgba(255, 246, 243, .5); color: #fff6f3; }
.tpl-asmara .asm-closing .asm-btn:hover { background: #fff6f3; color: #4a3336; }
.tpl-asmara .asm-credit {
    margin: 42px 0 0;
    font-family: var(--body);
    font-size: .5rem;
    letter-spacing: .32em;
    text-transform: uppercase;
    color: rgba(255, 246, 243, .4);
}

/* ---------------------------------------------------------------------
   Efek khas: hati melayang lembut
   --------------------------------------------------------------------- */
.asm-hearts {
    position: fixed;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    overflow: hidden;
}
.asm-hearts span {
    position: absolute;
    bottom: -30px;
    width: 10px;
    height: 10px;
    background: rgba(217, 163, 168, .5);
    transform: rotate(45deg);
    animation: asm-heart-rise linear infinite;
}
.asm-hearts span::before,
.asm-hearts span::after {
    content: '';
    position: absolute;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: inherit;
}
.asm-hearts span::before { top: -5px; left: 0; }
.asm-hearts span::after { top: 0; left: -5px; }
@keyframes asm-heart-rise {
    0% { transform: translateY(0) rotate(45deg) scale(.7); opacity: 0; }
    12% { opacity: .8; }
    100% { transform: translateY(-112vh) rotate(45deg) scale(1.15); opacity: 0; }
}

/* ---------------------------------------------------------------------
   Responsive
   --------------------------------------------------------------------- */
@media (max-width: 860px) {
    .tpl-asmara .asm-couple-grid { grid-template-columns: 1fr; gap: 22px; }
    .tpl-asmara .asm-connector { flex-direction: row; }
    .tpl-asmara .asm-connector-line { width: 42px; height: 1px; }
    .tpl-asmara .asm-event-grid { grid-template-columns: 1fr; }
    .tpl-asmara .asm-gallery { grid-template-columns: repeat(2, 1fr); grid-auto-rows: 190px; }
}

@media (max-width: 680px) {
    .tpl-asmara .asm-countdown { grid-template-columns: repeat(2, 1fr); }
    .tpl-asmara .asm-gift-grid { grid-template-columns: 1fr; }
    .tpl-asmara .asm-heart-line::before { left: 18px; }
    .tpl-asmara .asm-story-item { grid-template-columns: 38px 1fr; gap: 12px; }
    .tpl-asmara .asm-story-dot { grid-column: 1; grid-row: 1 / 3; }
    .tpl-asmara .asm-story-card,
    .tpl-asmara .asm-story-item:nth-child(even) .asm-story-card {
        grid-column: 2;
        grid-row: 1;
        text-align: left;
    }
    .tpl-asmara .asm-photo.is-wide { grid-column: span 2; }
    .tpl-asmara .asm-cover-foot { font-size: 1rem; }
}

/* ASMARA — hati melayang, parallax lembut, dan kilau potret. */
(function () {
    'use strict';

    if (!document.body.classList.contains('tpl-asmara')) return;

    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var finePointer = window.matchMedia('(pointer: fine)').matches;

    /* Hati kecil naik pelan dari bawah layar. */
    function startHearts() {
        if (reduceMotion || document.querySelector('.asm-hearts')) return;

        var layer = document.createElement('div');
        layer.className = 'asm-hearts';
        layer.setAttribute('aria-hidden', 'true');

        for (var i = 0; i < 16; i += 1) {
            var heart = document.createElement('span');
            var size = 6 + Math.random() * 7;
            heart.style.left = (Math.random() * 100).toFixed(2) + '%';
            heart.style.width = size.toFixed(1) + 'px';
            heart.style.height = size.toFixed(1) + 'px';
            heart.style.animationDuration = (14 + Math.random() * 14).toFixed(1) + 's';
            heart.style.animationDelay = (-Math.random() * 22).toFixed(1) + 's';
            heart.style.opacity = (0.25 + Math.random() * 0.35).toFixed(2);
            layer.appendChild(heart);
        }

        document.body.appendChild(layer);
    }

    /* Parallax foto sampul. */
    function startCoverParallax() {
        var image = document.querySelector('.asm-cover-media img');
        if (!image || reduceMotion || !finePointer) return;

        var frame = null;

        document.addEventListener('mousemove', function (event) {
            if (frame) return;
            frame = window.requestAnimationFrame(function () {
                var x = (event.clientX / window.innerWidth - 0.5) * 16;
                var y = (event.clientY / window.innerHeight - 0.5) * 16;
                image.style.transform = 'scale(1.06) translate3d(' + x.toFixed(2) + 'px,' + y.toFixed(2) + 'px,0)';
                frame = null;
            });
        }, { passive: true });
    }

    /* Potret mempelai sedikit "hidup" saat disentuh. */
    function startPortraitTilt() {
        if (reduceMotion || !finePointer) return;

        document.querySelectorAll('.asm-portrait').forEach(function (portrait) {
            portrait.addEventListener('pointermove', function (event) {
                var rect = portrait.getBoundingClientRect();
                var x = (event.clientX - rect.left) / rect.width - 0.5;
                var y = (event.clientY - rect.top) / rect.height - 0.5;
                portrait.style.transform = 'perspective(700px) rotateY(' + (x * 8).toFixed(2) + 'deg) rotateX(' + (-y * 8).toFixed(2) + 'deg) translateY(-3px)';
            }, { passive: true });

            portrait.addEventListener('pointerleave', function () {
                portrait.style.transform = '';
            });
        });
    }

    window.setTimeout(function () {
        startHearts();
        startCoverParallax();
        startPortraitTilt();
    }, 800);
})();

