/* NIRMALA — sorot proyektor, film strip yang bisa digeser, dan sinematik halus. */
(function () {
    'use strict';

    if (!document.body.classList.contains('tpl-nirmala')) return;

    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var finePointer = window.matchMedia('(pointer: fine)').matches;

    /* Sorot lampu proyektor mengikuti kursor. */
    function startBeam() {
        if (reduceMotion || !finePointer) return;

        var beam = document.createElement('div');
        beam.className = 'nir-beam';
        beam.setAttribute('aria-hidden', 'true');
        document.body.appendChild(beam);

        var frame = null;

        document.addEventListener('mousemove', function (event) {
            if (frame) return;
            frame = window.requestAnimationFrame(function () {
                beam.style.setProperty('--nir-x', event.clientX + 'px');
                beam.style.setProperty('--nir-y', event.clientY + 'px');
                beam.style.opacity = '1';
                frame = null;
            });
        }, { passive: true });
    }

    /* Film strip: geser dengan drag, roda mouse, atau sentuhan. */
    function startFilmstrip() {
        document.querySelectorAll('[data-drag-scroll]').forEach(function (strip) {
            var startX = 0;
            var startLeft = 0;
            var dragging = false;

            strip.addEventListener('pointerdown', function (event) {
                if (event.target.closest('button') && event.pointerType === 'mouse') {
                    /* tetap izinkan klik lightbox, drag dimulai setelah gerak */
                }
                dragging = true;
                startX = event.clientX;
                startLeft = strip.scrollLeft;
                strip.classList.add('is-dragging');
            });

            strip.addEventListener('pointermove', function (event) {
                if (!dragging) return;
                var delta = event.clientX - startX;
                if (Math.abs(delta) > 4) {
                    strip.setPointerCapture(event.pointerId);
                    strip.scrollLeft = startLeft - delta;
                }
            });

            function stopDrag() {
                dragging = false;
                strip.classList.remove('is-dragging');
            }

            strip.addEventListener('pointerup', stopDrag);
            strip.addEventListener('pointercancel', stopDrag);
            strip.addEventListener('pointerleave', function () {
                if (!strip.hasPointerCapture) stopDrag();
            });

            strip.addEventListener('wheel', function (event) {
                if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
                if (strip.scrollWidth <= strip.clientWidth) return;
                event.preventDefault();
                strip.scrollLeft += event.deltaY;
            }, { passive: false });
        });
    }

    /* Angka bab muncul dengan jeda lembut saat terlihat. */
    function startChapterCount() {
        if (reduceMotion || !('IntersectionObserver' in window)) return;

        var nodes = document.querySelectorAll('.nir-chapter strong');
        var observer = new IntersectionObserver(function (entries) {
            entries.forEach(function (entry) {
                if (!entry.isIntersecting) return;
                entry.target.style.transition = 'opacity .8s ease, transform .8s ease';
                entry.target.style.opacity = '1';
                entry.target.style.transform = 'translateY(0)';
                observer.unobserve(entry.target);
            });
        }, { threshold: 0.6 });

        nodes.forEach(function (node) {
            node.style.opacity = '0';
            node.style.transform = 'translateY(6px)';
            observer.observe(node);
        });
    }

    window.setTimeout(function () {
        startBeam();
        startFilmstrip();
        startChapterCount();
    }, 700);
})();

