434:     private function syncEvents(Wedding $wedding, array $rows): void
435:     {
436:         $kept = [];
437:         foreach (array_values($rows) as $i => $row) {
438:             if (empty($row['name'])) {
439:                 continue;
440:             }
441:             $attrs = [
442:                 'name' => $row['name'],
443:                 'event_date' => $row['event_date'] ?? null,
444:                 'start_time' => $row['start_time'] ?? null,
445:                 'end_time' => $row['end_time'] ?? null,
446:                 'venue_name' => $row['venue_name'] ?? null,
447:                 'address' => $row['address'] ?? null,
448:                 'maps_url' => $row['maps_url'] ?? null,
449:                 'sort_order' => $i,
450:             ];
451:             $event = ! empty($row['id'])
452:                 ? $wedding->events()->whereKey($row['id'])->first()
453:                 : null;
454:             if ($event) {
455:                 $event->update($attrs);
456:             } else {
457:                 $event = $wedding->events()->create($attrs);
458:             }
459:             $kept[] = $event->id;
460:         }
461:         $wedding->events()->whereNotIn('id', $kept)->delete();
462:     }
