105:     public function import(Request $request): RedirectResponse
106:     {
107:         $user = $request->user();
108:         $request->validate([
109:             'wedding_id' => ['required', 'integer'],
110:             'file' => ['required', 'file', 'mimes:csv,txt', 'max:5120'],
111:         ]);
112: 
113:         $wedding = $user->weddings()->findOrFail($request->integer('wedding_id'));
114:         $package = $user->activePackage();
115:         if (! $package->allow_export) {
116:             return back()->withErrors(['file' => 'Impor tamu tersedia pada paket Basic dan Premium.']);
117:         }
118: 
119:         $current = $wedding->guests()->count();
120:         $remaining = max(0, $package->max_guests - $current);
121:         if ($remaining === 0) {
122:             return back()->withErrors(['file' => "Batas {$package->max_guests} tamu untuk paket {$package->name} sudah tercapai."]);
123:         }
124: 
125:         $handle = fopen($request->file('file')->getRealPath(), 'r');
126:         if (! $handle) {
127:             return back()->withErrors(['file' => 'File tidak dapat dibaca.']);
128:         }
129: 
130:         $firstLine = fgets($handle);
131:         rewind($handle);
132:         $delimiter = ',';
133:         if ($firstLine !== false) {
134:             foreach ([';' => ';', "\t" => "\t"] as $candidate) {
135:                 if (substr_count($firstLine, $candidate) > substr_count($firstLine, $delimiter)) {
136:                     $delimiter = $candidate;
137:                 }
138:             }
139:         }
140: 
141:         $header = fgetcsv($handle, 0, $delimiter) ?: [];
142:         $map = $this->mapHeaders($header);
143:         if (! isset($map['name'])) {
144:             fclose($handle);
145: 
146:             return back()->withErrors(['file' => 'Header CSV harus memiliki kolom nama. Contoh: nama,telepon,grup,kuota']);
147:         }
148: 
149:         $rows = [];
150:         $skipped = 0;
151:         while (($line = fgetcsv($handle, 0, $delimiter)) !== false) {
152:             if (count($rows) >= min($remaining, config('wedding.limits.import_rows', 2000))) {
153:                 break;
154:             }
155:             $name = trim((string) ($line[$map['name']] ?? ''));
156:             if ($name === '') {
157:                 $skipped++;
158: 
159:                 continue;
160:             }
161:             $rows[] = [
162:                 'name' => mb_substr($name, 0, 100),
163:                 'phone' => $this->cell($line, $map, 'phone'),
164:                 'group_name' => $this->cell($line, $map, 'group'),
165:                 'max_pax' => max(1, min(20, (int) ($this->cell($line, $map, 'pax') ?: 2))),
166:             ];
167:         }
168:         fclose($handle);
169: 
170:         DB::transaction(function () use ($wedding, $rows) {
171:             foreach ($rows as $row) {
172:                 $wedding->guests()->create($row);
173:             }
174:         });
175: 
176:         return back()->with('status', count($rows).' tamu berhasil diimpor'.($skipped ? ", {$skipped} baris dilewati" : '').'.');
177:     }
