264:     private function cell(array $line, array $map, string $key): ?string
265:     {
266:         if (! isset($map[$key])) {
267:             return null;
268:         }
269:         $value = trim((string) ($line[$map[$key]] ?? ''));
270: 
271:         return $value !== '' ? $value : null;
272:     }
