242:     private function mapHeaders(array $header): array
243:     {
244:         $aliases = [
245:             'name' => ['nama', 'name', 'tamu', 'nama_tamu'],
246:             'phone' => ['telepon', 'phone', 'whatsapp', 'no_hp', 'nomor', 'hp'],
247:             'group' => ['grup', 'group', 'kategori', 'kelompok'],
248:             'pax' => ['kuota', 'pax', 'jumlah', 'jumlah_tamu', 'max_pax'],
249:         ];
250:         $map = [];
251:         foreach ($header as $i => $value) {
252:             $key = strtolower(trim((string) $value));
253:             $key = str_replace([' ', '-'], '_', $key);
254:             foreach ($aliases as $target => $names) {
255:                 if (in_array($key, $names, true)) {
256:                     $map[$target] = $i;
257:                 }
258:             }
259:         }
260: 
261:         return $map;
262:     }
